def listening_tcp_ports(start_port: int, end_port: int) -> list[int]:
    discovered = discover_tracy_listeners(start_port, end_port)
    if discovered:
        return sorted({listener.port for listener in discovered})
    ports = {f"{port:04X}": port for port in range(start_port, end_port + 1)}
    found: set[int] = set()
    for table in (Path("/proc/net/tcp"), Path("/proc/net/tcp6")):
        try:
            lines = table.read_text(encoding="utf-8").splitlines()[1:]
        except OSError:
            continue
        for line in lines:
            columns = line.split()
            if len(columns) < 4:
                continue
            local_address = columns[1]
            state = columns[3]
            if state != "0A":
                continue
            port_hex = local_address.rsplit(":", 1)[-1].upper()
            if port_hex in ports:
                found.add(ports[port_hex])
    return sorted(found)


def parse_ss_tracy_listeners(output: str, start_port: int, end_port: int) -> list[TracyListener]:
    listeners: list[TracyListener] = []
    seen: set[int] = set()
    for line in output.splitlines():
        tokens = line.split()
        local = next((token for token in tokens if re.search(r":\d+$", token) or re.search(r"\]:\d+$", token)), "")
        match = re.search(r":(\d+)$", local)
        if not match:
            continue
        port = int(match.group(1))
        if port < start_port or port > end_port or port in seen:
            continue
        process_match = re.search(r'\("([^"]+)"', line)
        pid_match = re.search(r"pid=(\d+)", line)
        listeners.append(
            TracyListener(
                port=port,
                pid=int(pid_match.group(1)) if pid_match else None,
                process=process_match.group(1) if process_match else None,
                source="ss",
            )
        )
        seen.add(port)
    return sorted(listeners, key=lambda listener: listener.port)


def discover_tracy_listeners(start_port: int = 8086, end_port: int = 8110) -> list[TracyListener]:
    listeners: dict[int, TracyListener] = {}
    ss = shutil.which("ss")
    if ss:
        try:
            result = subprocess.run(
                [ss, "-H", "-ltnp"],
                text=True,
                stdout=subprocess.PIPE,
                stderr=subprocess.DEVNULL,
                timeout=2,
                check=False,
            )
            if result.returncode == 0:
                listeners.update({listener.port: listener for listener in parse_ss_tracy_listeners(result.stdout, start_port, end_port)})
        except Exception:
            pass
    ports = {f"{port:04X}": port for port in range(start_port, end_port + 1)}
    for table in (Path("/proc/net/tcp"), Path("/proc/net/tcp6")):
        try:
            lines = table.read_text(encoding="utf-8").splitlines()[1:]
        except OSError:
            continue
        for line in lines:
            columns = line.split()
            if len(columns) < 4 or columns[3] != "0A":
                continue
            port_hex = columns[1].rsplit(":", 1)[-1].upper()
            port = ports.get(port_hex)
            if port is not None:
                listeners.setdefault(port, TracyListener(port=port))
    return [listeners[port] for port in sorted(listeners)]


RUST_OPENGL_CONFORMANCE_TEST = (
    "render::vulkanic::backends::opengl::conformance::"
    "isolated_opengl_conformance_renders_indexed_textured_draw"
)
RUST_SHADER_GBUFFER_SCENE_TEST = (
    "render::vulkanic::world_primitive_frontend::tests::"
    "rust_owned_shader_pack_mesh_scene_matches_opengl_and_vulkan_when_available"
)


def rust_test_binary_candidates(root: Path) -> list[Path]:
    deps = root / "src" / "main" / "rust" / "target" / "debug" / "deps"
    if not deps.is_dir():
        return []
    candidates = [
        path
        for path in deps.glob("mattmc_rust-*")
        if path.is_file() and os.access(path, os.X_OK) and path.suffix not in {".d", ".rlib", ".rmeta"}
    ]
    return sorted(candidates, key=lambda path: path.stat().st_mtime, reverse=True)


def resolve_rust_test_binary(root: Path, *, build_if_missing: bool = True) -> Path:
    candidates = rust_test_binary_candidates(root)
    if candidates:
        return candidates[0]
    if build_if_missing:
        result = subprocess.run(
            [
                "cargo",
                "test",
                "--manifest-path",
                str(root / "src" / "main" / "rust" / "Cargo.toml"),
                RUST_OPENGL_CONFORMANCE_TEST,
                "--no-run",
            ],
            cwd=root,
            text=True,
            stdout=subprocess.PIPE,
            stderr=subprocess.STDOUT,
            timeout=120,
            check=False,
        )
        if result.returncode == 0:
            candidates = rust_test_binary_candidates(root)
            if candidates:
                return candidates[0]
        raise RuntimeError(f"failed to build Rust test binary for RenderDoc:\n{result.stdout}")
    raise FileNotFoundError("compiled mattmc_rust test binary was not found")


def build_rust_shader_gbuffer_test_binary(root: Path) -> Path:
    result = subprocess.run(
        [
            "cargo",
            "test",
            "--manifest-path",
            str(root / "src" / "main" / "rust" / "Cargo.toml"),
            RUST_SHADER_GBUFFER_SCENE_TEST,
            "--no-run",
        ],
        cwd=root,
        text=True,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        timeout=180,
        check=False,
    )
    if result.returncode != 0:
        raise RuntimeError(f"failed to build Rust shader G-buffer test binary:\n{result.stdout}")
    return resolve_rust_test_binary(root, build_if_missing=False)


def build_rust_opengl_renderdoc_command(root: Path, capture_template: Path) -> tuple[list[str], dict[str, str]]:
    renderdoc = local_renderdoccmd_path()
    if not renderdoc:
        raise FileNotFoundError("renderdoccmd is not installed")
    binary = resolve_rust_test_binary(root)
    env = os.environ.copy()
    env["MATTMC_RENDERDOC_CAPTURE"] = "1"
    env["MATTMC_OPENGL_STRICT"] = "1"
    env["MATTMC_GRAPHICS_RUN_TYPE"] = "renderdoc-capture"
    return (
        [
            renderdoc,
            "capture",
            "-w",
            "-d",
            str(root),
            "-c",
            str(capture_template),
            str(binary),
            RUST_OPENGL_CONFORMANCE_TEST,
            "--nocapture",
        ],
        env,
    )


def find_validation_layer_manifest_path() -> Path | None:
    candidates: list[Path] = []
    vulkan_sdk = os.environ.get("VULKAN_SDK")
    if vulkan_sdk:
        candidates.append(Path(vulkan_sdk) / "share" / "vulkan" / "explicit_layer.d" / "VkLayer_khronos_validation.json")
    if platform_name() == "linux":
        candidates.extend(
            [
                Path("/usr/share/vulkan/explicit_layer.d/VkLayer_khronos_validation.json"),
                Path("/usr/local/share/vulkan/explicit_layer.d/VkLayer_khronos_validation.json"),
                Path("/etc/vulkan/explicit_layer.d/VkLayer_khronos_validation.json"),
            ]
        )
    for candidate in candidates:
        if candidate.is_file():
            return candidate
    return None


def shaderc_compiler_fingerprint() -> dict[str, object]:
    cargo_toml = CURRENT_REPO_ROOT / "src" / "main" / "rust" / "Cargo.toml"
    cargo_lock = CURRENT_REPO_ROOT / "src" / "main" / "rust" / "Cargo.lock"
    source = CURRENT_REPO_ROOT / "src" / "main" / "rust" / "render" / "vulkanic" / "backends" / "vulkan" / "shaderc_spirv_compiler.rs"
    version = None
    features: list[str] = []
    if cargo_toml.is_file():
        text = cargo_toml.read_text(encoding="utf-8", errors="replace")
        match = re.search(r"shaderc\s*=\s*\{[^}]*version\s*=\s*\"([^\"]+)\"", text)
        if match:
            version = match.group(1)
        features_match = re.search(r"shaderc\s*=\s*\{[^}]*features\s*=\s*\[([^\]]*)\]", text)
        if features_match:
            features = [part.strip().strip("\"'") for part in features_match.group(1).split(",") if part.strip()]
    if version is None and cargo_lock.is_file():
        text = cargo_lock.read_text(encoding="utf-8", errors="replace")
        match = re.search(r'name = "shaderc"\s+version = "([^"]+)"', text)
        if match:
            version = match.group(1)
    return {
        "name": "mattmc_rust:shaderc",
        "crate": "shaderc",
        "version": version,
        "features": features,
        "source": str(source) if source.is_file() else None,
        "cargo_toml": str(cargo_toml) if cargo_toml.is_file() else None,
        "cargo_lock": str(cargo_lock) if cargo_lock.is_file() else None,
    }


def tool_fingerprint() -> dict[str, object]:
    validation_manifest = find_validation_layer_manifest_path()
    renderdoc_path = local_renderdoccmd_path()
    tracy_path = local_tracy_capture_path()
    tracy = {"available": bool(tracy_path), "path": tracy_path, "version": None}
    if tracy_path:
        try:
            result = subprocess.run([tracy_path, "--help"], text=True, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, timeout=8, check=False)
            tracy["version"] = result.stdout.strip().splitlines()[0] if result.stdout.strip() else f"exit={result.returncode}"
        except Exception as exc:
            tracy["version"] = f"version-unavailable: {exc}"
    return {
        "vulkaninfo": executable_version("vulkaninfo"),
        "shader_compiler": shaderc_compiler_fingerprint(),
        "khronos_validation": {
            "available": validation_manifest is not None,
            "manifest": str(validation_manifest) if validation_manifest else None,
        },
        "renderdoc_vulkan_layer": {
            "local_manifest": str(local_renderdoc_layer_manifest_path()) if local_renderdoc_layer_manifest_path() else None,
        },
        "renderdoccmd": executable_version(renderdoc_path) if renderdoc_path else executable_version("renderdoccmd"),
        "tracy_capture": tracy,
        "tracy_csvexport": executable_version(local_tracy_csvexport_path()) if local_tracy_csvexport_path() else executable_version("tracy-csvexport"),
        "tracy_profiler": executable_version("tracy-profiler"),
    }


def run_type_for_args(args: argparse.Namespace) -> str:
    return run_type_for_effective_options(
        getattr(args, "validation", "off"),
        renderdoc=getattr(args, "renderdoc_capture", False),
        tracy=getattr(args, "tracy_capture", False),
    )


def run_type_for_effective_options(validation: str, *, renderdoc: bool, tracy: bool) -> str:
    enabled = []
    if validation != "off":
        enabled.append("vulkan-validation")
    if renderdoc:
        enabled.append("renderdoc-capture")
    if tracy:
        enabled.append("tracy-capture")
    if len(enabled) > 1:
        raise SystemExit("select only one instrumented run type at a time: validation, RenderDoc, or Tracy")
    return enabled[0] if enabled else "clean-performance"


def validation_profile_details(profile: str) -> dict[str, object]:
    normalized = "routine" if profile == "standard" else profile
    if normalized == "off":
        return {"profile": "off", "features": [], "performance_comparable": True}
    if normalized == "routine":
        return {
            "profile": "routine",
            "features": ["core", "synchronization", "best-practices"],
            "performance_comparable": False,
            "fail_severity": "warning",
        }
    if normalized == "deep":
        return {
            "profile": "deep",
            "features": ["gpu-assisted", "synchronization", "best-practices", "optional-debug-printf"],
            "performance_comparable": False,
            "fail_severity": "info",
        }
    return {"profile": normalized, "features": [], "performance_comparable": False}


VALIDATION_LINE_RE = re.compile(
    r"(?P<severity>ERROR|WARNING|INFO|VERBOSE)?[:\\s-]*"
    r"(?P<type>VALIDATION|PERFORMANCE|GENERAL)?[^\\n]*?"
    r"(?P<vuid>VUID-[A-Za-z0-9_./:-]+)?[^\\n]*?"
    r"(?:(?:MessageID|message id|msgNum|Message Id Name)\\s*[=: ]\\s*(?P<message_id>[A-Za-z0-9_./:-]+))?",
    re.IGNORECASE,
)
VALIDATION_OBJECT_RE = re.compile(
    r"(?:Object\s*\d*:\s*|object\s+|handle\s*=\s*)"
    r"(?P<handle>0x[0-9a-fA-F]+)"
    r"(?:[^,\n]*,\s*(?:type\s*=\s*)?(?P<type>VK_OBJECT_TYPE_[A-Z0-9_]+|[A-Za-z][A-Za-z0-9_]*))?"
    r"(?:[^,\n]*,\s*(?:name|debug name)\s*=\s*(?P<name>[^,\]\n]+))?",
    re.IGNORECASE,
)
VALIDATION_HANDLE_TYPE_RE = re.compile(
    r"handle\s*=\s*(?P<handle>0x[0-9a-fA-F]+)"
    r"\s*,\s*type\s*=\s*(?P<type>VK_OBJECT_TYPE_[A-Z0-9_]+|[A-Za-z][A-Za-z0-9_]*)"
    r"(?:\s*,\s*(?:name|debug name)\s*=\s*(?P<name>[^,\]\n]+))?",
    re.IGNORECASE,
)
VALIDATION_INDEXED_OBJECT_RE = re.compile(
    r"^\s*\[\d+\]\s+(?P<type>Vk[A-Za-z0-9_]+)\s+(?P<handle>0x[0-9a-fA-F]+)"
    r"(?:\s+(?:name|debug name)\s*=\s*(?P<name>[^,\]\n]+))?",
    re.MULTILINE,
)


def validation_message_blocks(text: str) -> list[str]:
    blocks: list[list[str]] = []
    current: list[str] = []
    trigger = re.compile(
        r"^\s*(?:Validation (?:Error|Warning)|(?:ERROR|WARNING|INFO|VERBOSE)\s+(?:VALIDATION|PERFORMANCE|GENERAL)|"
        r"\[Vulkan Loader\]|UNASSIGNED-)",
        re.IGNORECASE,
    )
    for line in text.splitlines():
        # capture_runner's retained validation-events file uses rg -n lines.
        # Early errors may no longer be in the bounded primary-log tail.
        line = re.sub(r"^\d+:", "", line)
        if trigger.search(line):
            if current:
                blocks.append(current)
            if re.search(r"^\s*\[Vulkan Loader\]", line, re.IGNORECASE):
                blocks.append([line])
                current = []
            else:
                current = [line]
        elif current and not line.strip():
            blocks.append(current)
            current = []
        elif current:
            current.append(line)
    if current:
        blocks.append(current)
    return ["\n".join(block).strip() for block in blocks if block]


def parse_validation_objects(message: str) -> list[dict[str, object]]:
    objects: dict[str, dict[str, object]] = {}
    for match in VALIDATION_HANDLE_TYPE_RE.finditer(message):
        handle = match.group("handle")
        entry = objects.setdefault(
            handle.lower(),
            {
                "handle": handle,
                "type": None,
                "debug_name": None,
            },
        )
        entry["type"] = match.group("type")
        debug_name = match.group("name")
        if debug_name:
            entry["debug_name"] = debug_name.strip().strip("'\"")
    for match in VALIDATION_OBJECT_RE.finditer(message):
        handle = match.group("handle")
        if not handle:
            continue
        entry = objects.setdefault(
            handle.lower(),
            {
                "handle": handle,
                "type": None,
                "debug_name": None,
            },
        )
        object_type = match.group("type")
        debug_name = match.group("name")
        if object_type:
            entry["type"] = object_type
        if debug_name:
            entry["debug_name"] = debug_name.strip().strip("'\"")
    for match in VALIDATION_INDEXED_OBJECT_RE.finditer(message):
        handle = match.group("handle")
        entry = objects.setdefault(
            handle.lower(),
            {
                "handle": handle,
                "type": None,
                "debug_name": None,
            },
        )
        entry["type"] = match.group("type")
        debug_name = match.group("name")
        if debug_name:
            entry["debug_name"] = debug_name.strip().strip("'\"")
    return list(objects.values())


def validation_finding_category(message: str, vuid: str, message_type: str) -> str:
    lowered = message.lower()
    if "device lost" in lowered or "vk_error_device_lost" in lowered:
        return "device_loss"
    if "[vulkan loader]" in lowered or "env var 'vk_instance_layers'" in lowered or "insert instance layer" in lowered:
        return "loader_environment_notice"
    if "vk_layer_khronos_validation" in lowered and vuid == "UNASSIGNED":
        return "validation_configuration_notice"
    if "gpu-assisted" in lowered or "gpuav" in lowered:
        return "gpu_assisted"
    if "sync" in lowered or "synchronization" in lowered:
        return "synchronization"
    if vuid != "UNASSIGNED" or message_type in {"validation", "performance"}:
        return "concrete_api_vuid"
    return "validation_configuration_notice"


def parse_validation_findings(text: str) -> list[dict[str, object]]:
    findings: dict[tuple[object, ...], dict[str, object]] = {}
    occurrence = 0
    for message in validation_message_blocks(text):
        match = VALIDATION_LINE_RE.search(message)
        vuid_match = re.search(r"VUID-[A-Za-z0-9_./:-]+", message)
        severity_match = re.search(r"\b(ERROR|WARNING|INFO|VERBOSE)\b", message, re.IGNORECASE)
        type_match = re.search(r"\b(VALIDATION|PERFORMANCE|GENERAL)\b", message, re.IGNORECASE)
        message_id_match = re.search(
            r"(?:MessageID|message id|msgNum|Message Id Name|MessageIDName)\s*[=: ]\s*([A-Za-z0-9_./:-]+|0x[0-9a-fA-F]+)",
            message,
            re.IGNORECASE,
        )
        objects = parse_validation_objects(message)
        semantic_match = re.search(r"(?:GAL|callsite|operation|semantic_operation)[=: ]+([A-Za-z0-9_./:-]+)", message)
        vuid = vuid_match.group(0) if vuid_match else "UNASSIGNED"
        message_type = type_match.group(1).lower() if type_match else (match.group("type").lower() if match and match.group("type") else "unknown")
        normalized_message = re.sub(r"0x[0-9a-fA-F]+", "0x*", message.strip())
        occurrence += 1
        key = (
            vuid,
            message_id_match.group(1) if message_id_match else None,
            hashlib.sha256(normalized_message.encode("utf-8")).hexdigest(),
        )
        finding = findings.setdefault(
            key,
            {
                "vuid": key[0],
                "severity": severity_match.group(1).lower() if severity_match else "unknown",
                "message_type": message_type,
                "message_id": key[1],
                "message": message.strip(),
                "category": validation_finding_category(message, vuid, message_type),
                "first_occurrence": occurrence,
                "last_occurrence": occurrence,
                "count": 0,
                "objects": objects,
                "object_handles": sorted({str(obj["handle"]) for obj in objects}),
                "frame": first_number(message, r"frame[=: ]+(\d+)"),
                "pass": first_number(message, r"pass[=: ]+(\d+)"),
                "draw": first_number(message, r"draw[=: ]+(\d+)"),
                "queue": first_number(message, r"queue[=: ]+(\d+)"),
                "submission": first_number(message, r"submission[=: ]+(\d+)"),
                "semantic_operation": semantic_match.group(1) if semantic_match else None,
            },
        )
        finding["count"] = int(finding["count"]) + 1
        finding["last_occurrence"] = occurrence
        if objects:
            merged = {str(obj["handle"]).lower(): obj for obj in finding.get("objects", []) if isinstance(obj, dict) and obj.get("handle")}
            for obj in objects:
                merged[str(obj["handle"]).lower()] = obj
            finding["objects"] = list(merged.values())
            finding["object_handles"] = sorted({str(obj.get("handle")) for obj in finding["objects"] if isinstance(obj, dict) and obj.get("handle")})
    return list(findings.values())


def validation_category_counts(findings: Sequence[dict[str, object]]) -> dict[str, int]:
    counts: dict[str, int] = {}
    for finding in findings:
        category = str(finding.get("category") or "unknown")
        counts[category] = counts.get(category, 0) + int(finding.get("count") or 0)
    return counts


def concrete_validation_finding_count(findings: Sequence[dict[str, object]]) -> int:
    concrete_categories = {"concrete_api_vuid", "synchronization", "gpu_assisted", "device_loss"}
    return sum(int(finding.get("count") or 0) for finding in findings if finding.get("category") in concrete_categories)


def validation_proof(
    meta: Mapping[str, str],
    combined_logs: str,
    files: Mapping[str, Path | None],
    tool_kind: str,
    mode: ModeSpec,
    work_counts: Mapping[str, object],
    creation_counts: Mapping[str, object],
    deterministic_complete: bool,
    subsystem_complete: bool,
    frame_sample_window_complete: bool,
) -> dict[str, object]:
    profile = meta.get("validation_profile") or meta.get("validation_mode", "off")
    requested_details = validation_profile_details(str(profile))
    vk_layer_settings = meta.get("vk_layer_settings", "")
    requested_features = requested_details.get("features", [])
    applied_settings = [part.strip() for part in vk_layer_settings.split(",") if part.strip()]
    layer_loaded = (
        meta.get("validation_enabled", "").lower() == "true"
        and "VK_LAYER_KHRONOS_validation" in meta.get("vk_instance_layers", "")
        and (
            "VK_LAYER_KHRONOS_validation" in combined_logs
            or "libVkLayer_khronos_validation" in combined_logs
            or "Insert instance layer" in combined_logs
        )
    )
    no_filtering = not any(
        meta.get(name)
        for name in (
            "vk_validation_features_disabled",
            "vk_validation_message_filter",
            "vk_validation_mute",
        )
    )
    is_vulkan_validation_backend = mode.backend in {"vulkan", "rust-vulkan"}
    rust_vulkan_shell_workload = mode.backend == "rust-vulkan" and bool(
        re.search(
            r"gal\.frame\.(?:acquire|present) backend=vulkan|Rust VulkanicGAL GUI frame|rust_gal_backend_submissions[=: ]+[1-9]",
            combined_logs,
            re.IGNORECASE,
        )
    )
    meaningful_workload = not is_vulkan_validation_backend or (
        rust_vulkan_shell_workload
        or
        (tool_kind == "capture" and deterministic_complete and (int(work_counts.get("draw") or 0) > 0 or int(creation_counts.get("descriptor") or 0) > 0))
        or (
            tool_kind == "subsystem"
            and (
                subsystem_complete
                or int(work_counts.get("draw") or 0) > 0
                or int(work_counts.get("pass") or 0) > 0
                or int(creation_counts.get("pipeline") or 0) > 0
                or int(creation_counts.get("descriptor") or 0) > 0
            )
        )
        or (tool_kind == "gameplay" and frame_sample_window_complete and int(work_counts.get("draw") or 0) > 0)
    )
    run_id = meta.get("run_id", "")
    associated_files: dict[str, bool] = {}
    if run_id:
        # These are required evidence, not optional diagnostics. After run-ID
        # selection, a missing current log must still fail association proof.
        for name in ("run_log", "validation_events", "shader_summary"):
            path = files.get(name)
            associated_files[name] = path is not None and run_id in path.name
        for name, path in files.items():
            if path is None:
                continue
            if name in {"meta", "renderdoc_summary", "tracy_summary", "deterministic", "frame_benchmark", "subsystem_benchmark"}:
                continue
            associated_files[name] = run_id in path.name
    return {
        "profile": profile,
        "layer_loaded": layer_loaded,
        "validation_layer_manifest": meta.get("validation_layer_manifest"),
        "vk_instance_layers": meta.get("vk_instance_layers", ""),
        "vk_add_layer_path": meta.get("vk_add_layer_path", ""),
        "vk_loader_debug": meta.get("vk_loader_debug", ""),
        "requested_features": requested_features,
        "applied_layer_settings": applied_settings,
        "core_requested": profile not in {"off", ""},
        "synchronization_requested": any("validate_sync=true" == item for item in applied_settings),
        "best_practices_requested": any("validate_best_practices=true" == item for item in applied_settings),
        "gpu_assisted_requested": any(item.startswith("gpuav_enable=true") for item in applied_settings),
        "debug_printf_requested": any(item.startswith("printf_enable=true") for item in applied_settings),
        "no_message_filtering": no_filtering,
        "meaningful_vulkan_workload": meaningful_workload,
        "run_id": run_id,
        "process": {
            "gradle_pid": parse_number(meta.get("gradle_pid")),
            "client_pid": parse_number(meta.get("client_pid")),
            "exit_code": parse_number(meta.get("exit_code")),
        },
        "artifact_log_association": {
            "all_named_logs_match_run": all(associated_files.values()) if associated_files else False,
            "files": associated_files,
        },
        "workload_counts": dict(work_counts),
        "creation_counts": dict(creation_counts),
    }


def subsystem_workload_counts(subsystem_doc: dict[str, object] | None) -> tuple[dict[str, int], dict[str, int]]:
    work_counts = {"draw": 0, "dispatch": 0, "pass": 0, "transfer": 0, "vulkan_submission": 0}
    creation_counts = {"pipeline": 0, "descriptor": 0, "resource": 0}
    if not isinstance(subsystem_doc, dict):
        return work_counts, creation_counts
    workloads = subsystem_doc.get("workloads")
    if not isinstance(workloads, list):
        return work_counts, creation_counts
    max_submission = 0
    for workload in workloads:
        if not isinstance(workload, dict):
            continue
        counts = workload.get("counts")
        if isinstance(counts, dict):
            for key in ("draw", "dispatch", "pass", "transfer"):
                value = counts.get(key)
                if isinstance(value, (int, float)):
                    work_counts[key] += int(value)
            for key in ("pipeline", "descriptor", "resource"):
                value = counts.get(key)
                if isinstance(value, (int, float)):
                    creation_counts[key] += int(value)
            value = counts.get("submission")
            if isinstance(value, (int, float)):
                work_counts["vulkan_submission"] += int(value)
        last_submission = workload.get("lastSubmission")
        if isinstance(last_submission, (int, float)):
            max_submission = max(max_submission, int(last_submission))
    if work_counts["vulkan_submission"] == 0:
        work_counts["vulkan_submission"] = max_submission
    return work_counts, creation_counts


def utc_now() -> str:
    return datetime.now(timezone.utc).isoformat()


def timestamp() -> str:
    return datetime.now().strftime("%Y%m%d-%H%M%S")


def script_dir() -> Path:
    return Path(__file__).resolve().parent


def repo_root(start: Path | None = None) -> Path:
    current = (start or script_dir()).resolve()
    if current.is_file():
        current = current.parent
    while current != current.parent:
        if (current / "gradlew").is_file() or (current / "gradlew.bat").is_file():
            return current
        current = current.parent
    raise SystemExit(f"Could not find MattMC repository root from {start or script_dir()}")


def platform_name() -> str:
    raw = platform.system().strip().lower()
    if raw.startswith(("cygwin", "mingw", "msys")):
        return "windows"
    if raw == "darwin":
        return "macos"
    return raw or "unknown"


def command_text(command: list[str], *, cwd: Path) -> str:
    if not shutil.which(command[0]) and not Path(command[0]).exists():
        return ""
    result = subprocess.run(command, cwd=cwd, text=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE, check=False)
    return result.stdout.strip() if result.returncode == 0 else ""


def git_output(root: Path, *args: str) -> str:
    return command_text(["git", *args], cwd=root)


def repository_metadata(target: RepoTarget) -> dict[str, object]:
    status = git_output(target.root, "status", "--short")
    return {
        "target": target.name,
        "role": target.role,
        "path": str(target.root),
        "branch": git_output(target.root, "branch", "--show-current"),
        "commit": git_output(target.root, "rev-parse", "HEAD"),
        "dirty": bool(status),
        "status_short": status.splitlines() if status else [],
    }


def directory_helper(root: Path) -> Path | None:
    helper = root / "DevUtils" / "Common" / "platform" / "directory" / "directory_helper.py"
    return helper if helper.is_file() else None


def resolve_named_directory(root: Path, name: str) -> Path:
    helper = directory_helper(root)
    if helper is None:
        raise SystemExit(f"Directory helper is missing in repository: {root}")
    result = subprocess.run(
        [sys.executable, str(helper), name],
        cwd=root,
        text=True,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        check=False,
    )
    if result.returncode != 0:
        raise SystemExit(result.stderr.strip() or result.stdout.strip() or f"Could not resolve {name}")
    return Path(result.stdout.strip()).resolve()


def find_frozen_repo(current_root: Path, explicit: str | None = None) -> Path:
    if explicit:
        frozen = Path(explicit).expanduser().resolve()
        source = "--frozen-repo"
    else:
        frozen = resolve_named_directory(current_root, "java_perf_repo")
        source = "DevUtils/Common/platform/directory/directories.json:java_perf_repo"
    validate_repository_root(frozen, "Frozen Java", source)
    return frozen


def validate_repository_root(root: Path, label: str, source: str) -> None:
    if not root.is_dir():
        raise SystemExit(f"{label} repository path from {source} does not exist: {root}")
    if not ((root / "gradlew").is_file() or (root / "gradlew.bat").is_file()):
        raise SystemExit(f"{label} repository path from {source} is missing a Gradle wrapper: {root}")
    if not (root / ".git").is_dir():
        raise SystemExit(f"{label} repository path from {source} is missing .git: {root}")


def repository_resolution(current: Path, frozen: Path, explicit: str | None = None) -> dict[str, object]:
    return {
        "current": str(current.resolve()),
        "frozen": str(frozen.resolve()),
        "frozen_source": "--frozen-repo" if explicit else "DevUtils/Common/platform/directory/directories.json:java_perf_repo",
    }


def selected_current_root(args: argparse.Namespace) -> Path:
    explicit = getattr(args, "repo_root", None)
    if explicit:
        current = Path(explicit).expanduser().resolve()
        validate_repository_root(current, "Current", "--repo-root")
        return current
    current = repo_root()
    validate_repository_root(current, "Current", "repository root")
    return current


def select_targets(args: argparse.Namespace) -> dict[str, RepoTarget]:
    current = selected_current_root(args)
    frozen = find_frozen_repo(current, args.frozen_repo)
    return {
        "current": RepoTarget("current", current, "current-under-test"),
        "frozen": RepoTarget("frozen", frozen, "frozen-baseline"),
    }


def gradle_script(root: Path) -> Path:
    if platform_name() == "windows" and (root / "gradlew.bat").is_file():
        return root / "gradlew.bat"
    if (root / "gradlew").is_file():
        return root / "gradlew"
    if (root / "gradlew.bat").is_file():
        return root / "gradlew.bat"
    raise SystemExit(f"No Gradle wrapper found in {root}")


def run_dev_capture_entrypoint(root: Path) -> tuple[str, Path]:
    python_script = root / "DevUtils" / "Common" / "capture_runner.py"
    if python_script.is_file():
        return "python", python_script
    shell_script = root / "DevUtils" / "Common" / "capture_runner.sh"
    if shell_script.is_file():
        return "shell", shell_script
    raise SystemExit(f"Internal capture runner is missing in {root}")


def run_dev_capture_script(root: Path) -> Path:
    return run_dev_capture_entrypoint(root)[1]


def remove_client_arg_option(client_args: str, option: str) -> str:
    if not client_args:
        return ""
    try:
        tokens = shlex.split(client_args)
        filtered: list[str] = []
        skip_next = False
        for token in tokens:
            if skip_next:
                skip_next = False
                continue
            if token == option:
                skip_next = True
                continue
            if token.startswith(f"{option}="):
                continue
            filtered.append(token)
        return shlex.join(filtered)
    except ValueError:
        pass
    pattern = rf"(^|\s){re.escape(option)}(=[^\s]+|\s+[^\s]+)?"
    return re.sub(pattern, " ", client_args).strip()


def remove_client_arg_assignment(client_args: str, key: str) -> str:
    if not client_args:
        return ""
    try:
        return shlex.join(token for token in shlex.split(client_args) if not token.startswith(f"{key}="))
    except ValueError:
        pass
    pattern = rf"(^|\s){re.escape(key)}=[^\s]+"
    return re.sub(pattern, " ", client_args).strip()


def append_client_arg(client_args: str, arg: str) -> str:
    return " ".join(part for part in [client_args.strip(), arg.strip()] if part)


def stable_json_hash(value: object) -> str:
    payload = json.dumps(value, sort_keys=True, separators=(",", ":")).encode("utf-8")
    return hashlib.sha256(payload).hexdigest()


def directory_file_hash(path: Path, *, suffixes: set[str] | None = None, limit: int = 10000) -> dict[str, object]:
    if not path.is_dir():
        return {"status": "missing", "hash": None, "file_count": 0, "total_bytes": 0, "truncated": False}
    digest = hashlib.sha256()
    file_count = 0
    total_bytes = 0
    truncated = False
    for child in sorted(candidate for candidate in path.rglob("*") if candidate.is_file()):
        if suffixes is not None and child.suffix not in suffixes:
            continue
        rel = child.relative_to(path).as_posix()
        if rel == "session.lock":
            continue
        file_count += 1
        if file_count > limit:
            truncated = True
            break
        try:
            payload = child.read_bytes()
        except OSError:
            payload = b""
        total_bytes += len(payload)
        digest.update(rel.encode("utf-8"))
        digest.update(b"\0")
        digest.update(str(len(payload)).encode("ascii"))
        digest.update(b"\0")
        digest.update(hashlib.sha256(payload).hexdigest().encode("ascii"))
        digest.update(b"\n")
    return {
        "status": "ok",
        "hash": digest.hexdigest(),
        "file_count": file_count,
        "total_bytes": total_bytes,
        "truncated": truncated,
    }


def copy_optional_tree(source: Path, target: Path) -> None:
    if not source.exists():
        return
    if source.is_dir():
        if target.exists():
            shutil.rmtree(target)
        shutil.copytree(source, target)
    else:
        target.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(source, target)


def canonical_fixture_id(args: argparse.Namespace) -> str:
    scenario = getattr(args, "world_static_terrain_scenario", "") or "real-world"
    world = getattr(args, "world", "") or WORLD_PROFILES[getattr(args, "world_profile", "migration-gate")].world
    resource_pack = getattr(args, "world_static_terrain_resource_pack_scenario", "") or "vanilla"
    model_scenario = getattr(args, "world_mesh_model_scenario", "") or "hidden"
    text_scenario = getattr(args, "world_text_scenario", "") or "hidden"
    terrain_particle_scenario = getattr(args, "world_material_terrain_particle_scenario", "") or "hidden"
    weather_scenario = getattr(args, "world_weather_scenario", "") or "hidden"
    cloud_scenario = getattr(args, "world_cloud_scenario", "") or "hidden"
    background_scenario = getattr(args, "world_background_scenario", "") or "auto"
    dh_flags = "-".join(
        name
        for name, flag in (
            ("dh-opaque", "world_distant_horizons_opaque"),
            ("dh-non-water", "world_distant_horizons_non_water"),
            ("dh-water", "world_distant_horizons_water"),
            ("dh-texture-palette", "world_distant_horizons_texture_palette"),
        )
        if getattr(args, flag, False)
    ) or "dh-none"
    world_profile = getattr(args, "world_profile", "migration-gate")
    return f"{world}-{world_profile}-{scenario}-{resource_pack}-{model_scenario}-{text_scenario}-{terrain_particle_scenario}-{weather_scenario}-{cloud_scenario}-{background_scenario}-{dh_flags}-{PARITY_FIXTURE_SCHEMA}".replace("/", "_").replace(" ", "_")


def materialize_external_dh_fixture(args: argparse.Namespace, world_root: Path) -> None:
    """Install one bounded, ordinary world fixture shared by Current and Frozen.

    The fixture is a datapack rather than a renderer-side injection: both
    repositories load the same blocks through vanilla server ticking, while
    Current's semantic collector remains the only route-specific observer.
    """
    if not any(
        getattr(args, flag, False)
        for flag in (
            "world_distant_horizons_opaque",
            "world_distant_horizons_non_water",
            "world_distant_horizons_water",
            "world_distant_horizons_texture_palette",
        )
    ):
        return
    datapack = world_root / "datapacks" / "mattmc_dh_fixture"
    function_dir = datapack / "data" / "mattmc" / "function"
    tag_dir = datapack / "data" / "minecraft" / "tags" / "function"
    function_dir.mkdir(parents=True, exist_ok=True)
    tag_dir.mkdir(parents=True, exist_ok=True)
    # One 32x32 panel in the canonical camera's forward cone. The coordinates
    # are also consumed by DeterministicCameraCapture's external-fixture path.
    # Keep the 32x32 witness panel inside one lowest-detail DH section.  The
    # previous 42/489 origin crossed both the x=64 and z=512 section seams,
    # allowing different source generations to be correlated as one palette.
    panel_min_x, panel_min_z, panel_y = 64, 512, 81
    lines = [
        'tellraw @a {"text":"MattMC GUI text parity probe","color":"gold"}',
        f"forceload add {panel_min_x} {panel_min_z} {panel_min_x + 31} {panel_min_z + 31}",
        f"fill {panel_min_x} {panel_y - 1} {panel_min_z} {panel_min_x + 31} {panel_y - 1} {panel_min_z + 31} minecraft:stone",
        f"fill {panel_min_x} {panel_y} {panel_min_z} {panel_min_x + 15} {panel_y} {panel_min_z + 15} minecraft:yellow_terracotta",
        f"fill {panel_min_x + 16} {panel_y} {panel_min_z} {panel_min_x + 31} {panel_y} {panel_min_z + 15} minecraft:diamond_block",
        f"fill {panel_min_x} {panel_y} {panel_min_z + 16} {panel_min_x + 15} {panel_y} {panel_min_z + 31} minecraft:lapis_block",
        f"fill {panel_min_x + 16} {panel_y} {panel_min_z + 16} {panel_min_x + 31} {panel_y} {panel_min_z + 31} minecraft:redstone_ore",
        f"fill {panel_min_x} {panel_y + 1} {panel_min_z} {panel_min_x + 31} {panel_y + 4} {panel_min_z + 31} minecraft:air",
    ]
    if getattr(args, "world_distant_horizons_water", False):
        lines.extend(
            [
                f"fill {panel_min_x + 28} {panel_y} {panel_min_z + 24} {panel_min_x + 31} {panel_y} {panel_min_z + 27} minecraft:stone",
                f"fill {panel_min_x + 28} {panel_y + 1} {panel_min_z + 24} {panel_min_x + 31} {panel_y + 1} {panel_min_z + 27} minecraft:water",
            ]
        )
    # Run one tick after the load tag fires.  Integrated-server world loading
    # can invoke the load tag before the copied save's chunks/tickers are
    # attached; scheduling the same server-authored commands avoids a silent
    # no-op while remaining identical in Current and Frozen.
    (function_dir / "load.mcfunction").write_text(
        "schedule function mattmc:fixture 1t replace\n", encoding="utf-8"
    )
    (function_dir / "fixture.mcfunction").write_text("\n".join(lines) + "\n", encoding="utf-8")
    # Some copied saves are entered after the load tag has already fired. A
    # self-disabling tick hook makes the fixture lifecycle-independent: it
    # executes once after the world is live, then becomes a no-op once the
    # lapis witness exists.
    (function_dir / "tick.mcfunction").write_text(
        f"execute unless block {panel_min_x + 13} {panel_y} {panel_min_z + 25} minecraft:lapis_block run function mattmc:fixture\n",
        encoding="utf-8",
    )
    (tag_dir / "load.json").write_text(
        json.dumps({"values": ["mattmc:load"]}, sort_keys=True) + "\n", encoding="utf-8"
    )
    (tag_dir / "tick.json").write_text(
        json.dumps({"values": ["mattmc:tick"]}, sort_keys=True) + "\n", encoding="utf-8"
    )
    (world_root / "datapacks" / "mattmc_dh_fixture" / "pack.mcmeta").write_text(
        json.dumps(
            {"pack": {"pack_format": 71, "description": "MattMC shared DH parity fixture"}},
            sort_keys=True,
        )
        + "\n",
        encoding="utf-8",
    )


def materialize_external_model_fixture(args: argparse.Namespace, world_root: Path) -> None:
    """Install block-model witnesses into the shared copied world.

    Model scenarios must be present in both Current and Frozen copies. The
    Current client may reassert the same block through diagnostic setup, but
    this datapack is the authoritative cross-repository fixture.
    """
    scenario = str(getattr(args, "world_mesh_model_scenario", "") or "").strip().lower()
    blocks = {
        "chest": "minecraft:chest[facing=south]",
        "bed": "minecraft:red_bed[facing=south,part=foot,occupied=false]",
        "bell": "minecraft:bell[facing=south,attachment=floor]",
        "shulker": "minecraft:purple_shulker_box[facing=up]",
        "decorated-pot": "minecraft:decorated_pot",
        "conduit": "minecraft:conduit",
    }
    block = blocks.get(scenario)
    if block is None:
        return
    datapack = world_root / "datapacks" / "mattmc_model_fixture"
    function_dir = datapack / "data" / "mattmc_model_fixture" / "function"
    tag_dir = datapack / "data" / "minecraft" / "tags" / "function"
    function_dir.mkdir(parents=True, exist_ok=True)
    tag_dir.mkdir(parents=True, exist_ok=True)
    # Position produced by DEFAULT_PARITY_CAMERA and the model capture's
    # four-block sightline.
    lines = [
        "fill 145 98 528 147 98 530 minecraft:stone",
        "fill 145 99 528 147 101 530 minecraft:air",
        f"setblock 146 99 529 {block}",
    ]
    (function_dir / "load.mcfunction").write_text("schedule function mattmc_model_fixture:model_fixture 1t replace\n", encoding="utf-8")
    (function_dir / "model_fixture.mcfunction").write_text("\n".join(lines) + "\n", encoding="utf-8")
    (tag_dir / "load.json").write_text(json.dumps({"values": ["mattmc_model_fixture:load"]}, sort_keys=True) + "\n", encoding="utf-8")
    (datapack / "pack.mcmeta").write_text(
        json.dumps({"pack": {"pack_format": 71, "description": "MattMC shared model parity fixture"}}, sort_keys=True) + "\n",
        encoding="utf-8",
    )


def materialize_canonical_fixture(args: argparse.Namespace, targets: Mapping[str, RepoTarget], artifact_root: Path) -> Path:
    existing = getattr(args, "_canonical_fixture_run_source", None)
    if existing:
        return Path(existing)
    source_run = targets["current"].root / "run"
    world = getattr(args, "world", "") or WORLD_PROFILES[getattr(args, "world_profile", "migration-gate")].world
    source_world = source_run / "saves" / world
    if not source_world.is_dir():
        raise SystemExit(f"Canonical fixture source world is missing: {source_world}")
    fixture_root = artifact_root / ".canonical-fixtures" / canonical_fixture_id(args)
    run_root = fixture_root / "run"
    if not run_root.exists():
        run_root.mkdir(parents=True, exist_ok=True)
        for name in ("options.txt", "config", "resourcepacks", "assets", "Distant_Horizons_server_data", "voxelmap"):
            copy_optional_tree(source_run / name, run_root / name)
        apply_canonical_graphics_mode(run_root / "options.txt", getattr(args, "graphics_mode", "fancy"))
        # Shader-enabled parity must use byte-identical source inputs. Frozen
        # Java OpenGL is the authoritative baseline, so prefer its selected
        # pack when available; this does not modify Frozen or alter the Rust
        # lowering path, it only prevents Current from staging a different
        # shader archive into an allegedly equivalent fixture.
        frozen_shader = targets.get("frozen", targets["current"]).root / "run" / "shaderpacks" / EXPECTED_SHADER_PACK
        shader_source = frozen_shader if frozen_shader.is_file() else source_run / "shaderpacks"
        shader_destination = (
            run_root / "shaderpacks" / EXPECTED_SHADER_PACK
            if shader_source.is_file()
            else run_root / "shaderpacks"
        )
        copy_optional_tree(shader_source, shader_destination)
        (run_root / "saves").mkdir(parents=True, exist_ok=True)
        copy_optional_tree(source_world, run_root / "saves" / world)
        materialize_external_dh_fixture(args, run_root / "saves" / world)
        materialize_external_model_fixture(args, run_root / "saves" / world)
    if not any(getattr(args, flag, False) for flag in (
        "world_distant_horizons_opaque", "world_distant_horizons_non_water",
        "world_distant_horizons_water", "world_distant_horizons_texture_palette",
    )):
        apply_canonical_vanilla_dh_isolation(run_root / "config" / "DistantHorizons.toml")
    manifest = {
        "schema": PARITY_FIXTURE_SCHEMA,
        "fixture_id": canonical_fixture_id(args),
        "created_at": utc_now(),
        "source_repository": str(targets["current"].root),
        "source_run": str(source_run),
        "source_world": str(source_world),
        "run_root": str(run_root),
        "world": world,
        "world_static_terrain_scenario": getattr(args, "world_static_terrain_scenario", "") or "",
        "resource_pack_scenario": getattr(args, "world_static_terrain_resource_pack_scenario", "") or "",
        "model_scenario": getattr(args, "world_mesh_model_scenario", "") or "",
        "world_text_scenario": getattr(args, "world_text_scenario", "") or "",
        "terrain_particle_scenario": getattr(args, "world_material_terrain_particle_scenario", "") or "",
        "graphics_mode": getattr(args, "graphics_mode", "fancy"),
        "shader_pack": EXPECTED_SHADER_PACK,
        "camera": canonical_camera_options(args),
        "source_save_hash": directory_file_hash(source_world, suffixes={".mca"}),
        "canonical_save_hash": directory_file_hash(run_root / "saves" / world, suffixes={".mca"}),
        "canonical_config_hash": directory_file_hash(run_root / "config"),
    }
    manifest_path = fixture_root / "fixture_manifest.json"
    manifest_path.write_text(json.dumps(manifest, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    setattr(args, "_canonical_fixture_run_source", str(run_root))
    setattr(args, "_canonical_fixture_manifest", str(manifest_path))
    setattr(args, "_canonical_fixture_id", manifest["fixture_id"])
    setattr(args, "_canonical_fixture_source_save_hash", manifest["source_save_hash"]["hash"])
    return run_root


def apply_canonical_vanilla_dh_isolation(config_path: Path) -> None:
    """Isolate copied vanilla fixtures, including DH rendering and fade passes."""
    if not config_path.is_file():
        return
    original = config_path.read_text(encoding="utf-8")
    updated = original
    # enableRendering belongs to DebugWireframe; it does not disable LODs or
    # DH clouds. rendererMode controls the actual DH rendering entry points.
    for key, value in (("rendererMode", '"DISABLED"'), ("enableRendering", "false"),
                       ("vanillaFadeMode", '"NONE"'), ("lodOnlyMode", "false")):
        updated, count = re.subn(rf"(?m)^([ \t]*{key}[ \t]*=)[^\r\n]*", rf"\g<1> {value}", updated)
        if count != 1:
            raise ValueError(f"vanilla DH isolation requires exactly one {key} setting")
    if updated != original:
        config_path.write_text(updated, encoding="utf-8")


def apply_canonical_graphics_mode(options_path: Path, graphics_mode: str) -> None:
    """Set the copied fixture's graphics mode without touching either live run.

    The option is a deterministic input to both Current Rust Vulkan and Frozen
    OpenGL. Fabulous is needed to exercise the explicit Rust terrain-
    transparency handoff, so it must never be inferred from the backend or
    from a user's mutable options file.
    """
    mode_ids = {"fast": "0", "fancy": "1", "fabulous": "2"}
    try:
        mode_id = mode_ids[graphics_mode]
    except KeyError as error:
        raise ValueError(f"unsupported canonical graphics mode: {graphics_mode}") from error
    if not options_path.is_file():
        raise FileNotFoundError(f"canonical fixture options are missing: {options_path}")
    source = options_path.read_text(encoding="utf-8")
    rewritten, replacements = re.subn(
        r"(?m)^graphicsMode:[^\r\n]*$",
        f"graphicsMode:{mode_id}",
        source,
    )
    if replacements != 1:
        raise ValueError("canonical fixture options must declare exactly one graphicsMode entry")
    options_path.write_text(rewritten, encoding="utf-8")


def canonical_parity_requested(modes: Sequence[ModeSpec]) -> bool:
    has_frozen_opengl = any(mode.target == "frozen" and mode.backend == "opengl" for mode in modes)
    has_current_rust_vulkan = any(mode.target == "current" and mode.backend == "rust-vulkan" for mode in modes)
    return has_frozen_opengl and has_current_rust_vulkan


def canonical_fixture_requested(args: argparse.Namespace, modes: Sequence[ModeSpec]) -> bool:
    """Return whether this run needs the shared world/camera fixture.

    Matrix parity naturally requests it through the paired Frozen/Current
    modes.  A focused Current-only terrain/resource-pack capture must use the
    same fixture as well; otherwise it silently runs the user's live world and
    has no canonical camera metadata, making the result non-comparable.

    Paired menu captures also require identical settings and pack inputs.
    Until there is a separate complete menu fixture contract, retain the
    shared fixture instead of silently using each repository's live inputs.
    An unpaired title observation does not need a copied world.
    """
    if canonical_parity_requested(modes):
        return True
    if bool(getattr(args, "title_screen_capture", False)) or bool(
        getattr(args, "title_screen_transition_capture", False)
    ):
        return False
    return any(
        bool(getattr(args, name, ""))
        for name in (
            "world_static_terrain_scenario",
            "world_static_terrain_resource_pack_scenario",
            "world_static_terrain_water_animation_capture",
            "world_distant_horizons_opaque",
            "world_distant_horizons_non_water",
            "world_distant_horizons_water",
            "world_distant_horizons_texture_palette",
            "world_mesh_model_scenario",
            "world_mesh_falling_block_scenario",
            "world_mesh_arrow_scenario",
            "world_item_entity_scenario",
            "world_experience_orb_scenario",
            "world_beacon_beam_scenario",
            "world_entity_flame_scenario",
            "world_entity_shadow_scenario",
            "world_entity_leash_scenario",
            "world_text_scenario",
            "world_material_terrain_particle_scenario",
            "world_mesh_primed_tnt_scenario",
            "world_mesh_piston_scenario",
            "world_weather_scenario",
            "world_cloud_scenario",
            "world_background_scenario",
            "world_border_scenario",
            "world_outline_scenario",
            "world_crack_scenario",
            "gui_resource_pack_scenario",
        )
    )


def canonical_camera_options(args: argparse.Namespace) -> dict[str, float | str]:
    camera = dict(DEFAULT_PARITY_CAMERA)
    if getattr(args, "model_camera", "world") == "sky":
        if (getattr(args, "world_mesh_model_scenario", "") != "cow"
                or getattr(args, "world_static_terrain_scenario", "")
                or getattr(args, "world_static_terrain_resource_pack_scenario", "")
                or getattr(args, "gui_resource_pack_scenario", "")
                or getattr(args, "world_cloud_scenario", "")
                or getattr(args, "capture_celestial", "")):
            raise ValueError("sky model camera requires only the cow model fixture, without terrain/cloud/celestial scenarios")
        # The existing no-gravity server cow follows the camera. Above the
        # dimension's build height no fixture support block can be placed;
        # both renderers see a genuinely terrain-free scene, not hidden draws.
        camera["y"] = 512.0
        camera["pitch"] = 0.0
        camera["pose_sequence"] = "cow-sky-static-v1"
    if getattr(args, "gui_resource_pack_scenario", "") == "water-bottom-isolation":
        camera["y"] = 96.0
        camera["pitch"] = -20.0
    if getattr(args, "capture_celestial", ""):
        camera["yaw"] = 0.0
        camera["pitch"] = -90.0
        camera["pose_sequence"] = "celestial-overhead-static-v1"
    if getattr(args, "world_cloud_scenario", "") in {"bounded", "fast"}:
        # The ordinary Origin pose is far below a sparse cloud field and looks
        # toward terrain, so it cannot establish visual cloud parity even when
        # both renderers submit clouds correctly. Observe the same copied
        # vanilla cloud layer from its height in both repositories; this is a
        # camera-only fixture change, not synthetic cloud geometry.
        camera["y"] = 192.0
        camera["pitch"] = 0.0
        camera["pose_sequence"] = "cloud-layer-static-v1"
        if getattr(args, "cloud_camera", "layer") == "overhead":
            camera["y"] = 160.0
            camera["pitch"] = -90.0
            camera["pose_sequence"] = "cloud-overhead-static-v1"
    return camera


def append_fixed_camera_jvm_options(args: argparse.Namespace, java_options: list[str]) -> None:
    if not getattr(args, "_canonical_fixture_run_source", None):
        return
    camera = canonical_camera_options(args)
    java_options.extend(
        [
            f"-Dmattmc.dev.deterministicCameraCapture.fixedX={camera['x']}",
            f"-Dmattmc.dev.deterministicCameraCapture.fixedY={camera['y']}",
            f"-Dmattmc.dev.deterministicCameraCapture.fixedZ={camera['z']}",
            f"-Dmattmc.dev.deterministicCameraCapture.fixedYaw={camera['yaw']}",
            f"-Dmattmc.dev.deterministicCameraCapture.fixedPitch={camera['pitch']}",
            f"-Dmattmc.dev.deterministicCameraCapture.cameraPathId={camera['pose_sequence']}",
        ]
    )


def canonical_fixture_uses_static_capture_schedule(args: argparse.Namespace) -> bool:
    """Whether this is a one-pose cross-repository visual fixture.

    Feature fixtures which need motion (translucency sorting, moving entities,
    weather, etc.) declare and validate their own capture schedule below.  The
    unscoped canonical Origin fixture and the bounded cloud-layer fixture are
    static probes. Both launchers must receive that fact as JVM properties:
    the Current Python runner otherwise defaults to a four-pose sweep while
    Frozen's shell runner uses one pose.
    """
    if not getattr(args, "_canonical_fixture_run_source", None):
        return False
    pose_sequence = canonical_camera_options(args)["pose_sequence"]
    if pose_sequence in {"cloud-layer-static-v1", "cloud-overhead-static-v1"}:
        return True
    if pose_sequence != "single-static-v1":
        return False
    return not any(
        bool(getattr(args, name, ""))
        for name in (
            "world_static_terrain_scenario",
            "world_static_terrain_resource_pack_scenario",
            "world_static_terrain_water_animation_capture",
            "world_distant_horizons_opaque",
            "world_distant_horizons_non_water",
            "world_distant_horizons_water",
            "world_distant_horizons_texture_palette",
            "world_mesh_model_scenario",
            "world_mesh_falling_block_scenario",
            "world_mesh_arrow_scenario",
            "world_item_entity_scenario",
            "world_experience_orb_scenario",
            "world_beacon_beam_scenario",
            "world_entity_flame_scenario",
            "world_entity_shadow_scenario",
            "world_entity_leash_scenario",
            "world_text_scenario",
            "world_material_terrain_particle_scenario",
            "world_mesh_primed_tnt_scenario",
            "world_mesh_piston_scenario",
            "world_weather_scenario",
            "world_cloud_scenario",
            "world_background_scenario",
            "world_border_scenario",
            "world_outline_scenario",
            "world_crack_scenario",
            "gui_resource_pack_scenario",
        )
    )


def add_parity_fixture_environment(args: argparse.Namespace, env: MutableMapping[str, str]) -> None:
    run_source = getattr(args, "_canonical_fixture_run_source", None)
    if not run_source:
        return
    camera = canonical_camera_options(args)
    env["MATTMC_CAPTURE_RUN_SOURCE"] = str(run_source)
    env["MATTMC_CAPTURE_WORLD_SOURCE"] = str(Path(run_source) / "saves" / args.world)
    env["MATTMC_PARITY_FIXTURE_SCHEMA"] = PARITY_FIXTURE_SCHEMA
    env["MATTMC_PARITY_FIXTURE_ID"] = str(getattr(args, "_canonical_fixture_id", canonical_fixture_id(args)))
    env["MATTMC_PARITY_FIXTURE_MANIFEST"] = str(getattr(args, "_canonical_fixture_manifest", ""))
    env["MATTMC_PARITY_FIXTURE_SOURCE_SAVE_HASH"] = str(getattr(args, "_canonical_fixture_source_save_hash", ""))
    env["MATTMC_PARITY_CAMERA_X"] = str(camera["x"])
    env["MATTMC_PARITY_CAMERA_Y"] = str(camera["y"])
    env["MATTMC_PARITY_CAMERA_Z"] = str(camera["z"])
    env["MATTMC_PARITY_CAMERA_YAW"] = str(camera["yaw"])
    env["MATTMC_PARITY_CAMERA_PITCH"] = str(camera["pitch"])
    env["MATTMC_PARITY_CAMERA_POSE_SEQUENCE"] = str(camera["pose_sequence"])


def read_json(path: Path) -> dict[str, object] | None:
    try:
        if path.exists():
            value = json.loads(path.read_text(encoding="utf-8"))
        else:
            # Historical evidence can be losslessly compacted without changing
            # the authoritative paths declared by its original manifests.
            with gzip.open(path.with_name(path.name + ".gz"), "rt", encoding="utf-8") as source:
                value = json.load(source)
    except Exception:
        return None
    return value if isinstance(value, dict) else None


def selected_source_execution_armed(capture_dir: Path) -> bool:
    status = read_json(
        capture_dir / "terrain_pass_contract" / "selected-source-admission-status.json"
    )
    return isinstance(status, dict) and bool(status.get("source_execution_armed"))


def selected_source_execution_observed(capture_dir: Path) -> bool:
    """Returns true only for an already-recorded native source submission.

    The Rust executor consumes its one-frame arm before it writes the receipt,
    so the live arm is deliberately not a timeout signal. A DH source receipt
    is a first-class selected-source workload and is not interchangeable with
    the static-terrain receipt family.
    """
    contract_dir = capture_dir / "terrain_pass_contract"
    for pattern in (
        "selected-source-execution-frame-*.json",
        "selected-source-execution-distant-horizons-frame-*.json",
    ):
        receipt_path = latest_matching(contract_dir, pattern)
        receipt = read_json(receipt_path) if receipt_path else None
        if not isinstance(receipt, dict):
            continue
        if (
            int(parse_number(receipt.get("frame_id")) or 0) > 0
            and int(parse_number(receipt.get("submission_id")) or 0) > 0
            and str(receipt.get("route") or "") == "rust-native-selected-source"
        ):
            return True
    return False


def rust_whole_frame_terrain_progress_observed(capture_dir: Path) -> bool:
    """Return true only after the live Rust terrain producer has reported work."""
    for log_path in sorted(capture_dir.rglob("runClient_*.log"), key=lambda path: path.stat().st_mtime, reverse=True):
        try:
            with log_path.open("rb") as stream:
                stream.seek(0, os.SEEK_END)
                # Particle/model fixtures can emit many semantic records after
                # terrain starts. Keep the scan bounded, but large enough that
                # those later records do not hide the earlier producer proof
                # before the parent timeout check runs.
                stream.seek(max(0, stream.tell() - 4 * 1024 * 1024), os.SEEK_SET)
                tail = stream.read().decode("utf-8", errors="replace")
        except (OSError, ValueError):
            continue
        if "Rust whole-frame terrain source " in tail and "inFlight=" in tail:
            return True
    # The Gradle-backed client runner can redirect its native log away from the
    # capture directory. Its bounded benchmark snapshot still carries the
    # producer counters, so use those as equivalent live progress evidence.
    for benchmark_path in sorted(
        capture_dir.rglob("graphics_frame_benchmark_*.json"),
        key=lambda path: path.stat().st_mtime if path.exists() else 0,
        reverse=True,
    )[:2]:
        benchmark = read_json(benchmark_path)
        if not isinstance(benchmark, dict):
            continue
        terrain = benchmark.get("staticTerrainScenario")
        if not isinstance(terrain, dict):
            continue
        accepted = int(parse_number(terrain.get("acceptedBuildOutputs")) or 0)
        visible = int(parse_number(terrain.get("visibleLayerSubmissions")) or 0)
        registered = int(parse_number(terrain.get("registeredMeshes")) or 0)
        if accepted > 0 or visible > 0 or registered > 0:
            return True
    return False


def read_key_values(path: Path | None) -> dict[str, str]:
    if path is None or not path.is_file():
        return {}
    values: dict[str, str] = {}
    for raw_line in path.read_text(encoding="utf-8", errors="replace").splitlines():
        if "=" not in raw_line:
            continue
        key, value = raw_line.split("=", 1)
        values[key.strip()] = value.strip()
    return values


def latest_matching(directory: Path, pattern: str) -> Path | None:
    matches = sorted(directory.glob(pattern), key=lambda path: path.stat().st_mtime if path.exists() else 0)
    return matches[-1] if matches else None


def parse_number(value: object) -> float | None:
    if isinstance(value, (int, float)):
        return float(value)
    if isinstance(value, str):
        try:
            return float(value.strip())
        except ValueError:
            return None
    return None


def static_terrain_geometry_evidence(doc: dict[str, object] | None) -> dict[str, object]:
    if not isinstance(doc, dict):
        return {"status": "fail", "failure": "geometry_truth_missing", "checked_events": 0}
    events = doc.get("recentEvents")
    if not isinstance(events, list) or not events:
        return {"status": "fail", "failure": "geometry_truth_missing", "checked_events": 0}
    checked = 0
    visible_checked = 0
    failures: list[str] = []
    landmark_events: list[dict[str, object]] = []
    expected_stride = int(
        parse_number(doc.get("expectedNativeVertexStride"))
        or parse_number(doc.get("activeNativeVertexStride"))
        or 0
    )
    previous_visible_key: tuple[object, object] | None = None
    visible_by_frame: dict[tuple[object, object, object, object], object] = {}
    visible_generation_by_frame: dict[tuple[object, object, object], set[int]] = {}
    executed_by_submission: set[tuple[object, object, object, object]] = set()
    mesh_content: dict[int, tuple[object, object, int]] = {}

    def number(event: dict[str, object], name: str) -> float | None:
        return parse_number(event.get(name))

    def nested_number(event: dict[str, object], parent: str, name: str) -> float | None:
        child = event.get(parent)
        if not isinstance(child, dict):
            return None
        return parse_number(child.get(name))

    def visible_event_frame_key(event: dict[str, object], gameplay_frame_id: int, enqueue_frame_id: int) -> int:
        frame_id = parse_number(event.get("frame"))
        if frame_id is not None:
            return int(frame_id)
        if event.get("gameplayFrameId") is not None:
            return gameplay_frame_id
        return enqueue_frame_id

    for raw_event in events:
        if not isinstance(raw_event, dict):
            continue
        reason = str(raw_event.get("reason") or "")
        if reason not in {
            "mesh-registered",
            "visible-submit",
            "stale-or-unregistered-submit",
            "executed-submit",
            "cross_world_stale_submission",
            "cross_world_stale_submission_unexpected_success",
        }:
            continue
        gameplay_frame_id = int(parse_number(raw_event.get("gameplayFrameId")) or 0)
        extraction_frame_id = int(parse_number(raw_event.get("terrainExtractionFrameId")) or 0)
        enqueue_frame_id = int(parse_number(raw_event.get("rustEnqueueFrameId")) or 0)
        execution_frame_id = int(parse_number(raw_event.get("executionFrameId")) or 0)
        execution_submission_id = int(parse_number(raw_event.get("executionSubmissionId")) or 0)
        mesh_key = int(parse_number(raw_event.get("meshKey")) or 0)
        content_hash = int(parse_number(raw_event.get("contentHash")) or 0)
        vertex_count = int(parse_number(raw_event.get("vertexCount")) or 0)
        buffer_vertex_capacity = int(parse_number(raw_event.get("bufferVertexCapacity")) or 0)
        vertex_stride = int(parse_number(raw_event.get("vertexStride")) or 0)
        index_count = int(parse_number(raw_event.get("indexCount")) or 0)
        max_index = int(parse_number(raw_event.get("maxIndex")) or -1)
        index_type = int(parse_number(raw_event.get("indexType")) or 0)
        section_count = int(parse_number(raw_event.get("sectionCount")) or 0)
        if mesh_key == 0 or vertex_count <= 0 or index_count <= 0 or section_count <= 0:
            failures.append("geometry_truth_missing")
            continue
        checked += 1
        if reason == "visible-submit":
            visible_checked += 1
            visible_key = (raw_event.get("sectionPos"), raw_event.get("layer"))
            visible_frame_key = visible_event_frame_key(raw_event, gameplay_frame_id, enqueue_frame_id)
            generation_key = (
                visible_frame_key,
                raw_event.get("sectionPos"),
                raw_event.get("layer"),
            )
            frame_visible_key = (
                generation_key[0],
                raw_event.get("sectionPos"),
                raw_event.get("layer"),
                int(parse_number(raw_event.get("visibleGeneration")) or 0),
            )
            if frame_visible_key in visible_by_frame:
                failures.append("duplicate_section_visible")
            visible_by_frame[frame_visible_key] = raw_event.get("meshKey")
            generation_set = visible_generation_by_frame.setdefault(generation_key, set())
            generation_set.add(int(parse_number(raw_event.get("visibleGeneration")) or 0))
            if len(generation_set) > 1:
                failures.append("stale_generation_overlap")
            if visible_key == previous_visible_key and raw_event.get("frame") is None and raw_event.get("gameplayFrameId") is None:
                failures.append("duplicate_section_visible")
            previous_visible_key = visible_key
        if reason == "executed-submit":
            executed_key = (
                execution_submission_id,
                raw_event.get("sectionPos"),
                raw_event.get("layer"),
                int(parse_number(raw_event.get("visibleGeneration")) or 0),
            )
            if execution_submission_id <= 0 or execution_frame_id <= 0:
                failures.append("execution_identity_missing")
            elif executed_key in executed_by_submission:
                failures.append("duplicate_section_execution")
            executed_by_submission.add(executed_key)
        if reason == "cross_world_stale_submission":
            failures.append("cross_world_stale_submission")
        if reason == "cross_world_stale_submission_unexpected_success":
            failures.append("cross_world_stale_submission_unexpected_success")
        if reason == "stale-or-unregistered-submit" or int(parse_number(raw_event.get("visibleGeneration")) or 0) not in {
            0,
            int(parse_number(raw_event.get("meshGeneration")) or 0),
        }:
            failures.append("stale_generation_visible")
        mesh_identity = (raw_event.get("sectionPos"), raw_event.get("layer"))
        previous_mesh = mesh_content.get(mesh_key)
        if previous_mesh is not None and previous_mesh[:2] != mesh_identity and previous_mesh[2] != content_hash:
            failures.append("mesh_key_collision")
        else:
            mesh_content[mesh_key] = (mesh_identity[0], mesh_identity[1], content_hash)
        if expected_stride > 0 and vertex_stride != expected_stride:
            failures.append("vertex_stride_invalid")
        if buffer_vertex_capacity > 0 and vertex_count > buffer_vertex_capacity:
            failures.append("vertex_count_exceeds_capacity")
        if index_type not in {1, 2}:
            failures.append("index_type_invalid")
        if max_index < 0 or max_index >= vertex_count:
            failures.append("index_range_invalid")
        if raw_event.get("vertexPositionsFinite") is not True:
            failures.append("non_finite_vertex_position")
        if raw_event.get("sectionOriginValid") is not True:
            failures.append("section_origin_mismatch")
        if raw_event.get("indexOffsetAlignmentValid") is not True:
            failures.append("index_alignment_invalid")
        lighting_flag_failures = {
            "normalContractValid": "terrain_lighting_normal_invalid",
            "aoContractValid": "terrain_lighting_ao_invalid",
            "blockSkyLightContractValid": "terrain_lighting_block_sky_invalid",
            "topFaceShadeContractValid": "terrain_lighting_top_shade_invalid",
        }
        for flag_name, failure_name in lighting_flag_failures.items():
            if raw_event.get(flag_name) is not True:
                failures.append(failure_name)
        if raw_event.get("separateAoActive") is True:
            separate_ao_vertices = int(parse_number(raw_event.get("separateAoVertexCount")) or 0)
            if separate_ao_vertices <= 0:
                failures.append("terrain_lighting_ao_missing")
            ao_range = raw_event.get("aoRange")
            if isinstance(ao_range, dict):
                min_ao = parse_number(ao_range.get("min"))
                max_ao = parse_number(ao_range.get("max"))
                if min_ao is None or max_ao is None or not (0.0 <= min_ao <= max_ao <= 1.0):
                    failures.append("terrain_lighting_ao_range_invalid")
            else:
                failures.append("terrain_lighting_ao_range_invalid")
        flag_failures = {
            "localBoundsValid": "geometry_out_of_bounds",
            "uvBoundsValid": "uv_bounds_invalid",
            "indexRangeValid": "index_range_invalid",
            "segmentLayoutValid": "segment_layout_invalid",
            "cameraBoundsFinite": "camera_bounds_invalid",
        }
        for flag_name, failure_name in flag_failures.items():
            if raw_event.get(flag_name) is not True:
                failures.append(failure_name)
        local_min_x = nested_number(raw_event, "localBounds", "minX")
        local_min_y = nested_number(raw_event, "localBounds", "minY")
        local_min_z = nested_number(raw_event, "localBounds", "minZ")
        local_max_x = nested_number(raw_event, "localBounds", "maxX")
        local_max_y = nested_number(raw_event, "localBounds", "maxY")
        local_max_z = nested_number(raw_event, "localBounds", "maxZ")
        bounds = [local_min_x, local_min_y, local_min_z, local_max_x, local_max_y, local_max_z]
        if any(value is None or not math.isfinite(value) for value in bounds):
            failures.append("geometry_out_of_bounds")
        elif (
            local_min_x < -8.01
            or local_min_y < -8.01
            or local_min_z < -8.01
            or local_max_x > 24.01
            or local_max_y > 24.01
            or local_max_z > 24.01
            or local_min_x > local_max_x
            or local_min_y > local_max_y
            or local_min_z > local_max_z
        ):
            failures.append("geometry_out_of_bounds")
        if len(landmark_events) < 8:
            landmark_events.append(
                {
                    "reason": reason,
                    "gameplayFrameId": gameplay_frame_id,
                    "terrainExtractionFrameId": extraction_frame_id,
                    "rustEnqueueFrameId": enqueue_frame_id,
                    "executionFrameId": execution_frame_id,
                    "executionSubmissionId": execution_submission_id,
                    "sectionPos": raw_event.get("sectionPos"),
                    "layer": raw_event.get("layer"),
                    "meshKey": mesh_key,
                    "contentHash": content_hash,
                    "vertexCount": vertex_count,
                    "bufferVertexCapacity": buffer_vertex_capacity,
                    "vertexStride": vertex_stride,
                    "indexCount": index_count,
                    "maxIndex": max_index,
                    "indexType": index_type,
                    "sectionCount": section_count,
                    "sectionOrigin": raw_event.get("sectionOrigin"),
                    "transformTranslation": raw_event.get("transformTranslation"),
                    "localBounds": raw_event.get("localBounds"),
                    "uvBounds": raw_event.get("uvBounds"),
                }
            )
    if checked <= 0:
        return {
            "status": "fail",
            "failure": "geometry_truth_missing",
            "checked_events": checked,
            "visible_submit_events": visible_checked,
            "landmark_events": landmark_events,
        }
    if visible_checked <= 0:
        failures.append("projected_landmark_missing")
    unique_failures = sorted(set(failures), key=static_terrain_failure_priority)
    return {
        "status": "pass" if not unique_failures else "fail",
        "failure": unique_failures[0] if unique_failures else None,
        "failures": unique_failures,
        "checked_events": checked,
        "visible_submit_events": visible_checked,
        "landmark_events": landmark_events,
    }


def static_terrain_translucent_evidence(
    doc: dict[str, object] | None,
    *,
    require_camera_sort: bool = False,
    require_unsupported_fluid: bool = False,
    native_camera_order: dict[str, object] | None = None,
) -> dict[str, object]:
    if not isinstance(doc, dict):
        return {"status": "skip", "failure": None, "checked_events": 0}
    events = doc.get("translucentEvents")
    if not isinstance(events, list):
        events = []
    if not events:
        return {"status": "fail", "failure": "terrain_translucent_events_missing", "checked_events": 0}

    failures: list[str] = []
    checked = 0
    mesh_events = 0
    sort_events = 0
    visible_events = 0
    executed_events = 0
    visible_by_frame: dict[int, list[int]] = {}
    latest_sort_by_mesh: dict[int, int] = {}
    executed_sort_by_mesh_frame: dict[tuple[int, int], set[int]] = {}
    section_identity_by_mesh: dict[int, object] = {}
    sorted_hashes_by_mesh: dict[int, set[int]] = {}
    source_sort_by_key: dict[tuple[int, int], dict[str, object]] = {}
    copied_sort_by_key: dict[tuple[int, int], dict[str, object]] = {}
    source_sort_events = 0
    rust_copy_events = 0
    primitive_accounting_events = 0
    unsupported_omitted_events = 0
    accounted_unsupported_primitives = 0
    accounted_omitted_primitives = 0
    sort_payload_diagnostics: list[dict[str, object]] = []
    primitive_accounting_diagnostics: list[dict[str, object]] = []
    landmark_events: list[dict[str, object]] = []
    sorter_type_counts: dict[str, int] = {}

    for raw_event in events:
        if not isinstance(raw_event, dict):
            continue
        if str(raw_event.get("layer") or "") != "TRANSLUCENT":
            continue
        reason = str(raw_event.get("reason") or "")
        if reason.startswith("translucent-fault-"):
            checked += 1
            fault = reason.removeprefix("translucent-fault-").split(":", 1)[0]
            fault_classification = {
                "sort-reversed": "terrain_translucent_sort_reversed",
                "sort-stale": "terrain_translucent_sort_stale",
                "sort-missing": "terrain_translucent_sort_missing",
                "duplicate-primitive": "terrain_translucent_duplicate_primitive",
                "index-out-of-range": "terrain_translucent_index_invalid",
                "index-type-invalid": "terrain_translucent_index_invalid",
                "index-alignment-invalid": "terrain_translucent_index_invalid",
                "sort-section-mismatch": "terrain_translucent_sort_section_mismatch",
                "old-new-overlap": "terrain_translucent_old_new_overlap",
                "section-order-reversed": "terrain_translucent_section_order_invalid",
                "depth-write-enabled": "terrain_translucent_depth_policy_invalid",
                "opaque-blend": "terrain_translucent_blend_policy_invalid",
                "cross-world-sort": "terrain_translucent_cross_world_sort",
                "source-sort-mismatch": "terrain_translucent_source_sort_mismatch",
                "sort-payload-corrupt": "terrain_translucent_sort_payload_corrupt",
                "primitive-metadata-missing": "terrain_translucent_primitive_metadata_missing",
                "primitive-kind-unknown": "terrain_translucent_primitive_unknown",
                "primitive-range-overlap": "terrain_translucent_primitive_range_overlap",
                "primitive-range-out-of-bounds": "terrain_translucent_primitive_range_out_of_bounds",
                "primitive-classification-swapped": "terrain_translucent_primitive_classification_swapped",
                "supported-primitive-omitted": "terrain_translucent_supported_primitive_omitted",
                "unsupported-primitive-executed": "terrain_translucent_unsupported_primitive_executed",
                "source-index-unknown-primitive": "terrain_translucent_source_index_unknown_primitive",
                "retained-index-duplicated": "terrain_translucent_retained_index_duplicated",
                "filtered-order-changed": "terrain_translucent_filtered_order_changed",
                "ordered-range-material-mismatch": "terrain_translucent_ordered_range_material_mismatch",
                "ordered-range-overlap": "terrain_translucent_ordered_range_overlap",
                "execution-order-hash-mismatch": "terrain_translucent_execution_order_hash_mismatch",
                "cross-generation-metadata": "terrain_translucent_cross_generation_metadata",
                "cross-world-primitive-range-reuse": "terrain_translucent_cross_world_primitive_range_reuse",
                "water-still-flow-texture-swapped": "terrain_water_still_flow_texture_swapped",
                "water-overlay-identity-invalid": "terrain_water_overlay_identity_invalid",
                "water-animation-entry-mismatch": "terrain_animation_frame_order_invalid",
                "water-animation-invalid-frame": "terrain_animation_frame_order_invalid",
                "water-animation-duplicate-frame": "terrain_animation_frame_order_invalid",
                "water-animation-missing-frame": "terrain_animation_frame_missing",
                "water-animation-zero-duration": "terrain_animation_frame_duration_invalid",
                "water-animation-duration-overflow": "terrain_animation_frame_duration_invalid",
                "water-animation-region-out-of-bounds": "terrain_animation_presented_frame_mismatch",
                "water-animation-missing-pixels": "terrain_animation_presented_frame_mismatch",
                "water-animation-incompatible-dimensions": "terrain_animation_presented_frame_mismatch",
                "water-animation-generation-mismatch": "terrain_animation_unexpected_resource_update",
                "water-animation-stale-generation": "terrain_animation_unexpected_resource_update",
                "water-animation-region-mismatch": "terrain_animation_presented_frame_mismatch",
                "water-animation-invalid-interp": "terrain_animation_interpolation_invalid",
                "water-animation-section-divergence": "terrain_animation_section_desynchronized",
                "water-animation-cross-world-state": "terrain_animation_unexpected_resource_update",
                "water-animation-per-frame-recreation": "terrain_animation_unexpected_resource_update",
                "water-corner-height-invalid": "terrain_water_geometry_invalid",
                "water-flow-reversed": "terrain_water_geometry_invalid",
                "water-uv-invalid": "terrain_water_geometry_invalid",
                "water-tint-invalid": "terrain_water_geometry_invalid",
                "water-light-swapped": "terrain_water_geometry_invalid",
                "water-normal-invalid": "terrain_water_geometry_invalid",
                "water-duplicate-face": "terrain_water_geometry_invalid",
                "water-missing-face": "terrain_water_geometry_invalid",
                "water-boundary-crack": "terrain_water_geometry_invalid",
                "water-depth-write-enabled": "terrain_water_depth_policy_invalid",
                "water-opaque-blend": "terrain_water_blend_policy_invalid",
                "water-stale-mesh-generation": "terrain_water_geometry_invalid",
                "water-glass-range-mismatch": "terrain_water_sort_range_invalid",
            }.get(fault)
            if fault_classification:
                failures.append(fault_classification)
            else:
                failures.append("terrain_translucent_events_missing")
            continue
        reason_base = reason.split(":", 1)[0]
        if reason_base not in {
            "mesh-registered",
            "translucent-source-sort",
            "translucent-rust-sort-copy",
            "translucent-sort-registered",
            "translucent-primitive-accounting",
            "translucent-sort-missing",
            "unsupported-fluid-omitted",
            "visible-submit",
            "executed-submit",
            "stale-or-unregistered-submit",
        }:
            continue
        checked += 1
        reason_base = reason.split(":", 1)[0]
        if reason_base == "unsupported-fluid-omitted":
            unsupported_omitted_events += 1
            continue
        frame_id = int(parse_number(raw_event.get("gameplayFrameId")) or parse_number(raw_event.get("frame")) or 0)
        mesh_key = int(parse_number(raw_event.get("meshKey")) or 0)
        mesh_generation = int(parse_number(raw_event.get("meshGeneration")) or 0)
        sort_generation = int(parse_number(raw_event.get("sortGeneration")) or 0)
        visible_generation = int(parse_number(raw_event.get("visibleGeneration")) or 0)
        index_upload_generation = int(parse_number(raw_event.get("indexUploadGeneration")) or 0)
        primitive_count = int(parse_number(raw_event.get("primitiveCount")) or 0)
        index_count = int(parse_number(raw_event.get("indexCount")) or 0)
        index_type = int(parse_number(raw_event.get("indexType")) or 0)
        sorted_index_hash = int(parse_number(raw_event.get("sortedIndexHash")) or 0)
        draw_order = int(parse_number(raw_event.get("translucentDrawOrder")) or 0)
        section_pos = raw_event.get("sectionPos")
        source_hash = int(parse_number(raw_event.get("sourceSortedIndexHash")) or 0)
        copied_hash = int(parse_number(raw_event.get("rustCopiedSortedIndexHash")) or 0)
        source_sample_hash = int(parse_number(raw_event.get("sourceSortedIndexSampleHash")) or 0)
        copied_sample_hash = int(parse_number(raw_event.get("rustCopiedSortedIndexSampleHash")) or 0)
        sorter_type = str(raw_event.get("sorterType") or "")
        sorted_index_sample = str(raw_event.get("sortedIndexSample") or "")
        detail = parse_colon_key_values(reason)
        if source_hash == 0:
            source_hash = int(parse_number(detail.get("sourceHash")) or 0)
        if copied_hash == 0:
            copied_hash = int(parse_number(detail.get("copiedHash")) or 0)
        if source_sample_hash == 0:
            source_sample_hash = int(parse_number(detail.get("sourceSampleHash")) or 0)
        if copied_sample_hash == 0:
            copied_sample_hash = int(parse_number(detail.get("copiedSampleHash")) or 0)
        if not sorter_type:
            sorter_type = str(detail.get("sorterType") or "")
        if sorter_type:
            sorter_type_counts[sorter_type] = sorter_type_counts.get(sorter_type, 0) + 1
        if not sorted_index_sample:
            sorted_index_sample = str(detail.get("sample") or "")
        if mesh_key == 0 or mesh_generation == 0 or index_count <= 0 or primitive_count <= 0:
            failures.append("terrain_translucent_sort_missing")
        if index_type != 2:
            failures.append("terrain_translucent_index_invalid")
        if reason_base == "mesh-registered":
            mesh_events += 1
            section_identity_by_mesh.setdefault(mesh_key, section_pos)
        elif reason_base == "translucent-primitive-accounting":
            mesh_events += 1
            primitive_accounting_events += 1
            section_identity_by_mesh.setdefault(mesh_key, section_pos)
            source_primitives = int(parse_number(detail.get("sourcePrimitives")) or 0)
            non_fluid_primitives = int(parse_number(detail.get("nonFluidPrimitives")) or 0)
            water_primitives = int(parse_number(detail.get("waterPrimitives")) or 0)
            unsupported_primitives = int(parse_number(detail.get("unsupportedPrimitives")) or 0)
            retained_primitives = int(parse_number(detail.get("retainedPrimitives")) or 0)
            omitted_primitives = int(parse_number(detail.get("omittedPrimitives")) or 0)
            accounted_unsupported_primitives += unsupported_primitives
            accounted_omitted_primitives += omitted_primitives
            executed_primitives = int(parse_number(detail.get("executedPrimitives")) or 0)
            source_indices = int(parse_number(detail.get("sourceIndices")) or 0)
            retained_indices = int(parse_number(detail.get("retainedIndices")) or 0)
            omitted_indices = int(parse_number(detail.get("omittedIndices")) or 0)
            range_count = int(parse_number(detail.get("rangeCount")) or 0)
            source_hash_detail = str(detail.get("sourceHash") or "")
            retained_hash_detail = str(detail.get("retainedHash") or "")
            water_still_primitives = int(parse_number(detail.get("waterStillPrimitives")) or 0)
            water_flow_primitives = int(parse_number(detail.get("waterFlowPrimitives")) or 0)
            water_overlay_primitives = int(parse_number(detail.get("waterOverlayPrimitives")) or 0)
            water_texture_switches = int(parse_number(detail.get("waterTextureSwitches")) or 0)
            water_animation_hash = int(parse_number(detail.get("waterAnimationHash")) or 0)
            water_animation_entries = str(detail.get("waterAnimationEntries") or "")
            sample = str(detail.get("sample") or "")
            if source_primitives <= 0:
                failures.append("terrain_translucent_primitive_accounting_invalid")
            if source_primitives != non_fluid_primitives + water_primitives + unsupported_primitives:
                failures.append("terrain_translucent_primitive_accounting_invalid")
            if retained_primitives != non_fluid_primitives + water_primitives:
                failures.append("terrain_translucent_supported_primitive_omitted")
            if omitted_primitives != unsupported_primitives:
                failures.append("terrain_translucent_unsupported_primitive_executed")
            if executed_primitives != retained_primitives:
                failures.append("terrain_translucent_execution_order_hash_mismatch")
            if source_indices != source_primitives * 6:
                failures.append("terrain_translucent_source_index_unknown_primitive")
            if retained_indices != retained_primitives * 6:
                failures.append("terrain_translucent_retained_index_duplicated")
            if omitted_indices != omitted_primitives * 6:
                failures.append("terrain_translucent_primitive_accounting_invalid")
            if source_indices != retained_indices + omitted_indices:
                failures.append("terrain_translucent_filtered_order_changed")
            if range_count <= 0 or retained_indices <= 0:
                failures.append("terrain_translucent_ordered_range_material_mismatch")
            if not source_hash_detail or source_hash_detail == "0" or not retained_hash_detail or retained_hash_detail == "0":
                failures.append("terrain_translucent_sort_payload_corrupt")
            if not sample:
                failures.append("terrain_translucent_primitive_accounting_invalid")
            if water_primitives > 0:
                water_identity_total = water_still_primitives + water_flow_primitives + water_overlay_primitives
                if water_identity_total != water_primitives:
                    failures.append("terrain_water_animation_entry_mismatch")
                if water_still_primitives <= 0 and water_flow_primitives <= 0:
                    failures.append("terrain_water_still_flow_texture_swapped")
                if water_animation_hash == 0 or not water_animation_entries or water_animation_entries == "missing":
                    failures.append("terrain_water_animation_entry_mismatch")
                if water_texture_switches < 0:
                    failures.append("terrain_water_animation_entry_mismatch")
            if len(primitive_accounting_diagnostics) < 16:
                primitive_accounting_diagnostics.append(
                    {
                        "frame": frame_id,
                        "sectionPos": section_pos,
                        "meshKey": mesh_key,
                        "meshGeneration": mesh_generation,
                        "sourcePrimitives": source_primitives,
                        "nonFluidPrimitives": non_fluid_primitives,
                        "waterPrimitives": water_primitives,
                        "unsupportedPrimitives": unsupported_primitives,
                        "retainedPrimitives": retained_primitives,
                        "omittedPrimitives": omitted_primitives,
                        "executedPrimitives": executed_primitives,
                        "sourceIndices": source_indices,
                        "retainedIndices": retained_indices,
                        "omittedIndices": omitted_indices,
                        "rangeCount": range_count,
                        "ranges": detail.get("ranges") or "",
                        "waterStillPrimitives": water_still_primitives,
                        "waterFlowPrimitives": water_flow_primitives,
                        "waterOverlayPrimitives": water_overlay_primitives,
                        "waterTextureSwitches": water_texture_switches,
                        "waterAnimationHash": water_animation_hash,
                        "waterAnimationEntries": water_animation_entries,
                        "sample": sample,
                    }
                )
        elif reason_base == "translucent-source-sort":
            source_sort_events += 1
            sort_events += 1
            if sort_generation <= 0 or index_upload_generation <= 0 or sorted_index_hash == 0 or source_hash == 0:
                failures.append("terrain_translucent_sort_missing")
            if source_hash and sorted_index_hash and source_hash != sorted_index_hash:
                failures.append("terrain_translucent_source_sort_mismatch")
            previous_sort = latest_sort_by_mesh.get(mesh_key)
            if previous_sort is not None and sort_generation <= previous_sort:
                failures.append("terrain_translucent_sort_stale")
            latest_sort_by_mesh[mesh_key] = max(sort_generation, previous_sort or 0)
            sorted_hashes_by_mesh.setdefault(mesh_key, set()).add(sorted_index_hash)
            source_sort_by_key[(mesh_key, sort_generation)] = {
                "frame": frame_id,
                "meshKey": mesh_key,
                "meshGeneration": mesh_generation,
                "sectionPos": section_pos,
                "sortGeneration": sort_generation,
                "hash": source_hash or sorted_index_hash,
                "sampleHash": source_sample_hash,
                "sample": sorted_index_sample,
                "sorterType": sorter_type,
                "cameraPosition": raw_event.get("cameraPosition"),
                "sortOrigin": raw_event.get("sortOrigin"),
                "primitiveCount": primitive_count,
                "indexCount": index_count,
                "indexType": index_type,
            }
            if source_sample_hash == 0 or not sorted_index_sample:
                failures.append("terrain_translucent_sort_payload_corrupt")
            if len(sort_payload_diagnostics) < 16:
                sort_payload_diagnostics.append({"kind": "source", **source_sort_by_key[(mesh_key, sort_generation)]})
        elif reason_base == "translucent-rust-sort-copy":
            rust_copy_events += 1
            if sort_generation <= 0 or index_upload_generation <= 0 or sorted_index_hash == 0 or copied_hash == 0:
                failures.append("terrain_translucent_sort_payload_corrupt")
            copied = {
                "frame": frame_id,
                "meshKey": mesh_key,
                "meshGeneration": mesh_generation,
                "sectionPos": section_pos,
                "sortGeneration": sort_generation,
                "hash": copied_hash or sorted_index_hash,
                "sampleHash": copied_sample_hash,
                "sample": sorted_index_sample,
                "sorterType": sorter_type,
                "cameraPosition": raw_event.get("cameraPosition"),
                "sortOrigin": raw_event.get("sortOrigin"),
                "primitiveCount": primitive_count,
                "indexCount": index_count,
                "indexType": index_type,
            }
            copied_sort_by_key[(mesh_key, sort_generation)] = copied
            source = source_sort_by_key.get((mesh_key, sort_generation))
            if source is not None:
                if source.get("meshGeneration") != mesh_generation:
                    failures.append("terrain_translucent_sort_generation_mismatch")
                if source.get("sectionPos") != section_pos:
                    failures.append("terrain_translucent_sort_section_mismatch")
                if source.get("hash") != copied["hash"] or source.get("sampleHash") != copied["sampleHash"]:
                    failures.append("terrain_translucent_source_sort_mismatch")
            if copied_sample_hash == 0 or not sorted_index_sample:
                failures.append("terrain_translucent_sort_payload_corrupt")
            if len(sort_payload_diagnostics) < 16:
                sort_payload_diagnostics.append({"kind": "rust-copy", **copied})
        elif reason_base == "translucent-sort-registered":
            sort_events += 1
            if sort_generation <= 0 or index_upload_generation <= 0 or sorted_index_hash == 0:
                failures.append("terrain_translucent_sort_missing")
            if source_hash and copied_hash and source_hash != copied_hash:
                failures.append("terrain_translucent_source_sort_mismatch")
            if source_sample_hash and copied_sample_hash and source_sample_hash != copied_sample_hash:
                failures.append("terrain_translucent_sort_payload_corrupt")
            sample_count = len([part for part in sorted_index_sample.split(",") if part.strip()])
            order_record = {
                "frame": frame_id,
                "meshKey": mesh_key,
                "sortGeneration": sort_generation,
                "sourceHash": source_hash,
                "copiedHash": copied_hash,
                "sourceSampleHash": source_sample_hash,
                "copiedSampleHash": copied_sample_hash,
                "sampleText": sorted_index_sample,
                "sample": sample_count,
                "sorterType": sorter_type,
                "cameraPosition": raw_event.get("cameraPosition"),
            }
            if len(sort_payload_diagnostics) < 16:
                sort_payload_diagnostics.append({"kind": "registered", **order_record})
            if sample_count <= 0:
                failures.append("terrain_translucent_sort_payload_corrupt")
        elif reason_base == "translucent-sort-missing":
            failures.append("terrain_translucent_sort_missing")
        elif reason_base == "visible-submit":
            visible_events += 1
            latest_sort = latest_sort_by_mesh.get(mesh_key)
            latest_copy = copied_sort_by_key.get((mesh_key, latest_sort or 0))
            if sort_generation <= 0 or sorted_index_hash == 0 or index_upload_generation <= 0:
                failures.append("terrain_translucent_sort_missing")
            elif latest_sort is not None and sort_generation != latest_sort:
                failures.append("terrain_translucent_sort_execution_stale")
            if latest_copy is not None and sorted_index_hash and latest_copy.get("hash") != sorted_index_hash:
                failures.append("terrain_translucent_sort_payload_corrupt")
            visible_by_frame.setdefault(frame_id, []).append(draw_order)
        elif reason_base == "executed-submit":
            executed_events += 1
            latest_sort = latest_sort_by_mesh.get(mesh_key)
            latest_copy = copied_sort_by_key.get((mesh_key, latest_sort or 0))
            if sort_generation <= 0 or sorted_index_hash == 0 or index_upload_generation <= 0:
                failures.append("terrain_translucent_sort_missing")
            elif latest_sort is not None and sort_generation != latest_sort:
                failures.append("terrain_translucent_sort_execution_stale")
            if latest_copy is not None and sorted_index_hash and latest_copy.get("hash") != sorted_index_hash:
                failures.append("terrain_translucent_sort_payload_corrupt")
            executed_sort_by_mesh_frame.setdefault((frame_id, mesh_key), set()).add(sort_generation)
        elif reason_base == "stale-or-unregistered-submit":
            failures.append("terrain_translucent_sort_stale")
        previous_section = section_identity_by_mesh.get(mesh_key)
        if previous_section is not None and previous_section != section_pos:
            failures.append("terrain_translucent_sort_section_mismatch")
        if len(landmark_events) < 8:
            landmark_events.append(
                {
                    "reason": reason,
                    "frame": frame_id,
                    "sectionPos": section_pos,
                    "meshKey": mesh_key,
                    "meshGeneration": mesh_generation,
                    "sortGeneration": sort_generation,
                    "visibleGeneration": visible_generation,
                    "primitiveCount": primitive_count,
                    "indexCount": index_count,
                    "indexType": index_type,
                    "sortedIndexHash": sorted_index_hash,
                    "indexUploadGeneration": index_upload_generation,
                    "drawOrder": draw_order,
                    "cameraPosition": raw_event.get("cameraPosition"),
                    "sortOrigin": raw_event.get("sortOrigin"),
                }
            )

    for orders in visible_by_frame.values():
        if len(orders) != len(set(orders)):
            failures.append("terrain_translucent_section_order_invalid")
    for (_frame_id, _mesh_key), executed_generations in executed_sort_by_mesh_frame.items():
        if len(executed_generations) > 1:
            failures.append("terrain_translucent_old_new_overlap")
    for key, source in source_sort_by_key.items():
        copied = copied_sort_by_key.get(key)
        if copied is None:
            failures.append("terrain_translucent_sort_payload_corrupt")
            continue
        if source.get("hash") != copied.get("hash"):
            failures.append("terrain_translucent_source_sort_mismatch")
        if source.get("sampleHash") != copied.get("sampleHash"):
            failures.append("terrain_translucent_sort_payload_corrupt")
        if source.get("meshGeneration") != copied.get("meshGeneration"):
            failures.append("terrain_translucent_sort_generation_mismatch")
        if source.get("sectionPos") != copied.get("sectionPos"):
            failures.append("terrain_translucent_sort_section_mismatch")

    if checked <= 0:
        failures.append("terrain_translucent_events_missing")
    if mesh_events <= 0:
        failures.append("terrain_translucent_sort_missing")
    if (source_sort_events > 0 or rust_copy_events > 0) and primitive_accounting_events <= 0:
        failures.append("terrain_translucent_primitive_accounting_invalid")
    if unsupported_omitted_events > 0 and (accounted_unsupported_primitives <= 0 or accounted_omitted_primitives <= 0):
        failures.append("terrain_translucent_unsupported_primitive_executed")
    if require_unsupported_fluid:
        if unsupported_omitted_events <= 0:
            failures.append("terrain_translucent_unsupported_metadata_missing")
        if accounted_unsupported_primitives <= 0 or accounted_omitted_primitives <= 0:
            failures.append("terrain_translucent_unsupported_metadata_missing")
    if visible_events <= 0:
        failures.append("terrain_translucent_section_order_invalid")
    if executed_events <= 0:
        failures.append("terrain_translucent_sort_missing")
    if require_camera_sort:
        if sort_events <= 0 or source_sort_events <= 0 or rust_copy_events <= 0:
            failures.append("terrain_translucent_sort_missing")
        if not any(len(hashes) >= 2 for hashes in sorted_hashes_by_mesh.values()) and not (
                isinstance(native_camera_order, dict) and native_camera_order.get("passed") is True):
            failures.append("terrain_translucent_sort_stale")
    unique_failures = sorted(set(failures), key=static_terrain_translucent_failure_priority)
    return {
        "status": "pass" if not unique_failures else "fail",
        "failure": unique_failures[0] if unique_failures else None,
        "failures": unique_failures,
        "checked_events": checked,
        "mesh_events": mesh_events,
        "sort_events": sort_events,
        "source_sort_events": source_sort_events,
        "rust_copy_events": rust_copy_events,
        "primitive_accounting_events": primitive_accounting_events,
        "unsupported_omitted_events": unsupported_omitted_events,
        "accounted_unsupported_primitives": accounted_unsupported_primitives,
        "accounted_omitted_primitives": accounted_omitted_primitives,
        "unsupported_fluid_required": require_unsupported_fluid,
        "visible_events": visible_events,
        "executed_events": executed_events,
        "camera_sort_required": require_camera_sort,
        "native_camera_order": native_camera_order,
        "sorted_hashes_by_mesh": {str(mesh): len(hashes) for mesh, hashes in sorted_hashes_by_mesh.items()},
        "sorter_type_counts": dict(sorted(sorter_type_counts.items())),
        "sort_payload_diagnostics": sort_payload_diagnostics,
        "primitive_accounting_diagnostics": primitive_accounting_diagnostics,
        "landmark_events": landmark_events,
    }


def parse_colon_key_values(text: str) -> dict[str, str]:
    values: dict[str, str] = {}
    for part in str(text or "").split(":")[1:]:
        if "=" not in part:
            continue
        key, value = part.split("=", 1)
        values[key] = value
    return values


def parse_water_animation_state(text: str) -> dict[str, dict[str, str]]:
    states: dict[str, dict[str, str]] = {}
    for part in str(text or "").split("|"):
        if "=" not in part:
            continue
        name, payload = part.split("=", 1)
        fields: dict[str, str] = {}
        for item in payload.split(","):
            if ":" not in item:
                continue
            key, value = item.split(":", 1)
            fields[key] = value
        states[name] = fields
    return states


def parse_water_animation_summary(text: str) -> dict[str, dict[str, object]]:
    summaries: dict[str, dict[str, object]] = {}
    for part in str(text or "").split("|"):
        tokens = part.split("/")
        width_token_index = next(
            (index for index, token in enumerate(tokens) if re.fullmatch(r"\d+x\d+", token or "")),
            -1,
        )
        if width_token_index < 2 or len(tokens) <= width_token_index + 5:
            continue
        location = "/".join(tokens[1:width_token_index])
        if location.endswith("water_still"):
            name = "still"
        elif location.endswith("water_flow"):
            name = "flow"
        elif location.endswith("water_overlay"):
            name = "overlay"
        else:
            continue
        entries: list[tuple[int, int]] = []
        for item in tokens[width_token_index + 5].split(","):
            if "@" not in item:
                continue
            frame_text, duration_text = item.split("@", 1)
            frame_index = parse_number(frame_text)
            duration = parse_number(duration_text)
            if frame_index is None or duration is None:
                continue
            entries.append((int(frame_index), max(1, int(duration))))
        summaries[name] = {
            "texture": int(parse_number(tokens[0]) or 0),
            "location": location,
            "frame_count": int(parse_number(tokens[width_token_index + 1]) or 0),
            "frame_ticks": int(parse_number(tokens[width_token_index + 2]) or 0),
            "frame_row_size": int(parse_number(tokens[width_token_index + 3]) or 0),
            "interpolation": int(parse_number(tokens[width_token_index + 4]) or 0),
            "entries": entries,
        }
    return summaries


def expected_water_animation_state(summary: Mapping[str, object], frame_tick: int) -> dict[str, int] | None:
    raw_entries = summary.get("entries")
    if not isinstance(raw_entries, list):
        return None
    if not raw_entries:
        if int(summary.get("frame_count") or 0) <= 1:
            return {
                "current": 0,
                "next": 0,
                "elapsed": 0,
                "duration": max(1, int(summary.get("frame_ticks") or 1)),
                "interpolation": int(summary.get("interpolation") or 0),
            }
        return None
    entries: list[tuple[int, int]] = []
    for raw in raw_entries:
        if not isinstance(raw, tuple) or len(raw) != 2:
            return None
        entries.append((int(raw[0]), max(1, int(raw[1]))))
    total_duration = sum(duration for _, duration in entries)
    if total_duration <= 0:
        return None
    cursor = frame_tick % total_duration
    elapsed = 0
    entry_index = 0
    for index, (_, duration) in enumerate(entries):
        if cursor < elapsed + duration:
            entry_index = index
            break
        elapsed += duration
    current, duration = entries[entry_index]
    next_frame, _ = entries[(entry_index + 1) % len(entries)]
    return {
        "current": current,
        "next": next_frame,
        "elapsed": cursor - elapsed,
        "duration": duration,
        "interpolation": int(summary.get("interpolation") or 0),
    }


def static_terrain_water_animation_dense_evidence(doc: dict[str, object] | None) -> dict[str, object]:
    if not isinstance(doc, dict):
        return {"status": "skip", "failure": None, "checked_frames": 0}
    dense = doc.get("rustGalStaticTerrainWaterAnimationDenseCapture")
    if not isinstance(dense, dict) or not dense.get("enabled"):
        return {"status": "skip", "failure": None, "checked_frames": 0}
    frames = dense.get("frames")
    if not isinstance(frames, list):
        frames = []
    requested = int(parse_number(dense.get("requestedFrames")) or 0)
    captured = int(parse_number(dense.get("capturedFrames")) or len(frames))
    failures: list[str] = []
    diagnostics: list[dict[str, object]] = []
    if not dense.get("complete"):
        failures.append("terrain_animation_frame_missing")
    if requested <= 0 or captured < requested or len(frames) < requested:
        failures.append("terrain_animation_frame_missing")

    previous_rendered_frame: int | None = None
    previous_atlas_generation: int | None = None
    previous_visible_submissions: int | None = None
    hashes: set[int] = set()
    still_states: list[str] = []
    flow_states: list[str] = []
    overlay_states: list[str] = []
    distinct_frame_keys: set[tuple[str, str]] = set()
    visual_hashes: set[str] = set()
    interpolation_progress: dict[str, list[float]] = {"still": [], "flow": [], "overlay": []}
    summary_by_name: dict[str, dict[str, object]] = {}
    checked = 0
    for expected_index, raw in enumerate(frames):
        if not isinstance(raw, dict):
            failures.append("terrain_animation_frame_missing")
            continue
        checked += 1
        index_value = parse_number(raw.get("index"))
        rendered_frame_value = parse_number(raw.get("renderedFrameIndex"))
        game_time_value = parse_number(raw.get("gameTime"))
        animation_hash_value = parse_number(raw.get("animationHash"))
        visible_submissions_value = parse_number(raw.get("visibleLayerSubmissions"))
        current_frame_submissions_value = parse_number(raw.get("currentFrameVisibleLayerSubmissions"))
        atlas_generation_value = parse_number(raw.get("atlasGeneration"))
        index = int(index_value) if index_value is not None else -1
        screenshot = str(raw.get("screenshot") or "")
        rendered_frame = int(rendered_frame_value) if rendered_frame_value is not None else -1
        game_time = int(game_time_value) if game_time_value is not None else -1
        animation_hash = int(animation_hash_value) if animation_hash_value is not None else 0
        animation_summary = str(raw.get("animationSummary") or "")
        animation_state = str(raw.get("animationState") or "")
        visible_submissions = int(visible_submissions_value) if visible_submissions_value is not None else 0
        current_frame_submissions = int(current_frame_submissions_value) if current_frame_submissions_value is not None else 0
        atlas_generation = int(atlas_generation_value) if atlas_generation_value is not None else 0
        if index != expected_index:
            failures.append("terrain_animation_frame_order_invalid")
        if not screenshot or not Path(screenshot).is_file():
            failures.append("terrain_animation_frame_missing")
        else:
            try:
                from PIL import Image

                with Image.open(screenshot) as image:
                    image = image.convert("RGB")
                    visual_hashes.add(hashlib.sha256(image.tobytes()).hexdigest()[:16])
                    image.thumbnail((64, 36))
                    pixels = list(image.getdata())
                    visible_pixels = sum(1 for red, green, blue in pixels if max(red, green, blue) > 24)
                    if not pixels or visible_pixels / max(1, len(pixels)) < 0.05:
                        failures.append("terrain_animation_presented_frame_mismatch")
            except Exception:
                failures.append("terrain_animation_frame_missing")
        if rendered_frame < 0 or (previous_rendered_frame is not None and rendered_frame <= previous_rendered_frame):
            failures.append("terrain_animation_frame_order_invalid")
        if game_time < 0:
            failures.append("terrain_animation_frame_order_invalid")
        if animation_hash == 0 or animation_summary == "missing" or not animation_summary:
            failures.append("terrain_animation_frame_order_invalid")
        elif not summary_by_name:
            summary_by_name = parse_water_animation_summary(animation_summary)
        if visible_submissions <= 0:
            failures.append("terrain_animation_presented_frame_mismatch")
        if previous_visible_submissions is not None and visible_submissions <= previous_visible_submissions:
            failures.append("terrain_animation_presented_frame_mismatch")
        if atlas_generation <= 0:
            failures.append("terrain_animation_unexpected_resource_update")
        if previous_atlas_generation is not None and atlas_generation != previous_atlas_generation:
            failures.append("terrain_animation_unexpected_resource_update")
        states = parse_water_animation_state(animation_state)
        for name, collector in (("still", still_states), ("flow", flow_states), ("overlay", overlay_states)):
            state = states.get(name)
            if not state or state.get("current") is None or state.get("next") is None:
                failures.append("terrain_animation_frame_missing")
            else:
                collector.append(f"{state.get('current')}->{state.get('next')}@{state.get('elapsed')}/{state.get('duration')}")
                distinct_frame_keys.add((name, str(state.get("current"))))
                interpolation = state.get("interpolation")
                if interpolation not in {"0", "1"}:
                    failures.append("terrain_animation_interpolation_invalid")
                summary = summary_by_name.get(name)
                expected = expected_water_animation_state(summary, rendered_frame) if summary else None
                if expected is None:
                    failures.append("terrain_animation_frame_order_invalid")
                else:
                    current = parse_number(state.get("current"))
                    next_frame = parse_number(state.get("next"))
                    elapsed = parse_number(state.get("elapsed"))
                    duration = parse_number(state.get("duration"))
                    if current is None or int(current) != expected["current"] or next_frame is None or int(next_frame) != expected["next"]:
                        failures.append("terrain_animation_frame_order_invalid")
                    if elapsed is None or int(elapsed) != expected["elapsed"] or duration is None or int(duration) != expected["duration"]:
                        failures.append("terrain_animation_frame_duration_invalid")
                    if int(expected["interpolation"]) != int(interpolation):
                        failures.append("terrain_animation_interpolation_invalid")
                    fraction = parse_number(state.get("fraction"))
                    if int(interpolation) == 1 and fraction is not None:
                        interpolation_progress[name].append(float(fraction))
        hashes.add(animation_hash)
        previous_rendered_frame = rendered_frame
        previous_atlas_generation = atlas_generation
        previous_visible_submissions = visible_submissions
        if len(diagnostics) < 8:
            diagnostics.append(
                {
                    "index": index,
                    "screenshot": screenshot,
                    "renderedFrameIndex": rendered_frame,
                    "gameTime": game_time,
                    "animationHash": animation_hash,
                    "atlasGeneration": atlas_generation,
                    "animationState": animation_state,
                    "visibleLayerSubmissions": visible_submissions,
                    "currentFrameVisibleLayerSubmissions": current_frame_submissions,
                }
            )

    if checked <= 0:
        failures.append("terrain_animation_frame_missing")
    if len(hashes) != 1:
        failures.append("terrain_animation_unexpected_resource_update")
    if len(set(still_states)) < 2 or len(set(flow_states)) < 2:
        failures.append("terrain_animation_frame_order_invalid")
    if not overlay_states:
        failures.append("terrain_animation_frame_missing")
    for name, progress in interpolation_progress.items():
        entries = summary_by_name.get(name, {}).get("entries")
        has_intermediate_interval = (
            isinstance(entries, list)
            and any(isinstance(entry, tuple) and len(entry) == 2 and int(entry[1]) > 1 for entry in entries)
        )
        if (
            summary_by_name.get(name, {}).get("interpolation") == 1
            and has_intermediate_interval
            and not any(0.0 < value < 1.0 for value in progress)
        ):
            failures.append("terrain_animation_interpolation_missing")
    if checked > 1 and len(visual_hashes) < 2:
        failures.append("terrain_animation_presented_frame_mismatch")
    unique_failures = sorted(set(failures), key=static_terrain_water_animation_failure_priority)
    return {
        "status": "pass" if not unique_failures else "fail",
        "failure": unique_failures[0] if unique_failures else None,
        "failures": unique_failures,
        "requested_frames": requested,
        "captured_frames": captured,
        "checked_frames": checked,
        "animation_hashes": sorted(hashes),
        "distinct_frame_keys": len(distinct_frame_keys),
        "visual_hashes": sorted(visual_hashes)[:16],
        "still_states": still_states[:16],
        "flow_states": flow_states[:16],
        "overlay_states": overlay_states[:16],
        "summary": summary_by_name,
        "diagnostics": diagnostics,
    }


def static_terrain_water_animation_failure_priority(failure: str) -> tuple[int, str]:
    priority = {
        "terrain_animation_frame_missing": 0,
        "terrain_animation_presented_frame_mismatch": 1,
        "terrain_animation_frame_order_invalid": 2,
        "terrain_animation_frame_duration_invalid": 3,
        "terrain_animation_wrap_invalid": 4,
        "terrain_animation_interpolation_missing": 5,
        "terrain_animation_interpolation_invalid": 6,
        "terrain_animation_section_desynchronized": 7,
        "terrain_animation_unexpected_resource_update": 8,
    }
    return (priority.get(failure, 50), failure)


def static_terrain_translucent_final_order_evidence(doc: dict[str, object] | None) -> dict[str, object]:
    if not isinstance(doc, dict):
        return {"status": "skip", "failure": None, "captures": 0}
    if not static_terrain_requires_translucent_camera_sort(str(doc.get("rustGalStaticTerrainScenario") or "")):
        return {"status": "skip", "failure": None, "captures": 0}
    captures = doc.get("captures")
    if not isinstance(captures, list):
        captures = []
    by_name = {str(item.get("poseName") or ""): item for item in captures if isinstance(item, dict)}
    required = ["translucent-front", "translucent-cross-opposite", "translucent-return"]
    if not all(name in by_name for name in required):
        return {
            "status": "fail",
            "failure": "terrain_translucent_final_order_invalid",
            "failures": ["terrain_translucent_final_order_invalid"],
            "captures": len(captures),
            "reason": "missing front/rear/return translucent overlap captures",
        }
    try:
        from PIL import Image, ImageDraw
    except ImportError:
        return {
            "status": "fail",
            "failure": "terrain_translucent_final_order_invalid",
            "failures": ["terrain_translucent_final_order_invalid"],
            "captures": len(captures),
            "reason": "Pillow unavailable for final translucent crop classification",
        }

    stats: dict[str, dict[str, object]] = {}
    failures: list[str] = []
    for pose_name in required:
        screenshot_value = by_name[pose_name].get("screenshot")
        screenshot = Path(str(screenshot_value or ""))
        if not screenshot.exists():
            failures.append("terrain_translucent_final_order_invalid")
            stats[pose_name] = {"status": "missing_screenshot", "screenshot": str(screenshot)}
            continue
        with Image.open(screenshot) as image:
            rgb = image.convert("RGB")
            pose_stats = translucent_overlap_crop_stats(rgb)
            if pose_stats.get("status") == "present":
                crop = pose_stats.get("crop")
                if isinstance(crop, tuple):
                    crop_path = screenshot.with_name(f"static_terrain_translucent_overlap_crop_{pose_name}.png")
                    rgb.crop(crop).save(crop_path)
                    pose_stats["crop_path"] = str(crop_path)
                    pose_stats["crop"] = {
                        "left": crop[0],
                        "top": crop[1],
                        "right": crop[2],
                        "bottom": crop[3],
                    }
            else:
                failures.append("terrain_translucent_final_order_invalid")
            stats[pose_name] = pose_stats

    front = stats.get("translucent-front", {})
    rear = stats.get("translucent-cross-opposite", {})
    returned = stats.get("translucent-return", {})
    if all(isinstance(item, dict) and item.get("status") == "present" for item in (front, rear, returned)):
        front_vector = color_ratio_vector(front)
        rear_vector = color_ratio_vector(rear)
        return_vector = color_ratio_vector(returned)
        front_rear_distance = sum(abs(front_vector[index] - rear_vector[index]) for index in range(3))
        front_return_distance = sum(abs(front_vector[index] - return_vector[index]) for index in range(3))
        if front_rear_distance < 0.08:
            failures.append("terrain_translucent_final_order_invalid")
        if front_return_distance > 0.12:
            failures.append("terrain_translucent_final_order_invalid")
        if int(front.get("filled_pixels") or 0) < 900 or int(rear.get("filled_pixels") or 0) < 900:
            failures.append("terrain_translucent_final_order_invalid")
        if float(front.get("edge_ratio") or 1.0) > 0.55 or float(rear.get("edge_ratio") or 1.0) > 0.55:
            failures.append("terrain_translucent_final_order_invalid")
        stats["comparison"] = {
            "frontRearColorDistance": front_rear_distance,
            "frontReturnColorDistance": front_return_distance,
            "expected": "front and rear camera positions must produce different filled overlap colors; return must match front",
        }
    unique_failures = sorted(set(failures), key=static_terrain_translucent_failure_priority)
    return {
        "status": "pass" if not unique_failures else "fail",
        "failure": unique_failures[0] if unique_failures else None,
        "failures": unique_failures,
        "captures": len(captures),
        "poses": stats,
    }


def translucent_camera_visual_evidence(baseline_doc, current_doc, tolerance=6.0):
    from native_terrain_order import POSES, capture_ack
    from PIL import Image, ImageChops, ImageStat
    if not any(isinstance(doc, dict) and doc.get("staticTerrainFixtureScenario") == "translucent-overlap"
               for doc in (baseline_doc, current_doc)):
        return None
    result = {"passed": False, "sampling_model": "observed-overlap-camera-interiors-v1", "poses": []}
    try:
        if any(doc.get("staticTerrainFixtureScenario") != "translucent-overlap"
               or [c["poseName"] for c in doc["captures"]] != list(POSES)
               for doc in (baseline_doc, current_doc)):
            raise ValueError("missing-matched-seven-pose-sequence")
        for index, (before, after, pose) in enumerate(zip(baseline_doc["captures"], current_doc["captures"], POSES), 1):
            equivalence = deterministic_visual_fixture_equivalence(
                {**baseline_doc, "captures": [before]}, {**current_doc, "captures": [after]})
            if equivalence["status"] != "passed":
                raise ValueError("incomparable-pose:" + pose + ":" + str(equivalence["mismatches"]))
            receipts = [capture_ack(capture) for capture in (before, after)]
            for capture, receipt in zip((before, after), receipts):
                if (capture["index"] != index or receipt["index"] != index
                        or receipt["poseName"] != pose or receipt["status"] != "captured"
                        or receipt["renderedFrameIndex"] != capture["renderedFrameIndex"]
                        or receipt["screenshot"] != capture["screenshot"]):
                    raise ValueError("unacknowledged-camera-pose:" + pose)
                expected = [capture["observedPitch"]] * 2 + [capture["observedYaw"]] * 2
                if receipt.get("cameraPoseHistory") != expected:
                    raise ValueError("unsettled-camera-history:" + pose)
            fixtures = [receipt["translucentFixtureProjection"] for receipt in receipts]
            for fixture in fixtures:
                if (fixture["fixture"] != "three-pane-crossing-v1" or fixture["cells"] != 42
                        or fixture["matchingCells"] != 42 or fixture["complete"] is not True
                        or not isinstance(fixture["points"], list) or len(fixture["points"]) != 9):
                    raise ValueError("incomplete-overlap-fixture:" + pose)
            if any(fixtures[0][key] != fixtures[1][key] for key in ("origin", "direction")):
                raise ValueError("different-overlap-placement:" + pose)
            mip_evidence = None
            mip_fixture = any("file/mattmc-water-mip-compatible" in
                              (doc.get("worldResourceReload") or {}).get("selectedAtCapture", [])
                              for doc in (baseline_doc, current_doc))
            if mip_fixture or any("atlasMipLevels" in fixture for fixture in fixtures):
                levels = [fixture["atlasMipLevels"] for fixture in fixtures]
                requested = [fixture["requestedAtlasMipLevels"] for fixture in fixtures]
                native = receipts[1]["nativeTerrainOrder"]["textureMipLevels"]
                if (any(type(value) is not int or not 1 <= value <= 32 for value in levels + requested + [native])
                        or levels[0] != levels[1] or levels[1] != native or requested[0] != requested[1]
                        or mip_fixture and levels[0] != requested[0]):
                    raise ValueError("mismatched-actual-atlas-mips:" + pose)
                mip_evidence = {"actual_levels": native, "requested_levels": requested[0]}
            boxes = []
            for point, other in zip(fixtures[0]["points"], fixtures[1]["points"]):
                if point is None and other is None:
                    continue
                if (not isinstance(point, list) or not isinstance(other, list)
                        or len(point) != 2 or len(other) != 2
                        or any(type(v) not in (int, float) or not math.isfinite(v) for v in point + other)
                        or any(abs(a - b) > 0.01 for a, b in zip(point, other))):
                    raise ValueError("incomparable-overlap-projection:" + pose)
                x, y = (round(v) for v in point)
                if 2 <= x < 1278 and 2 <= y < 718:
                    boxes.append((x - 2, y - 2, x + 3, y + 3))
            if (len(set(boxes)) != len(boxes)
                    or pose in (POSES[0], POSES[3], POSES[-1]) and len(boxes) != 9):
                raise ValueError("missing-overlap-interiors:" + pose)
            with Image.open(before["screenshot"]) as a, Image.open(after["screenshot"]) as b:
                a, b = a.convert("RGB"), b.convert("RGB")
                if a.size != (1280, 720) or b.size != a.size:
                    raise ValueError("incomparable-camera-extent:" + pose)
                error = ImageStat.Stat(ImageChops.difference(a, b)).mean
                regions = [{"crop_box": box,
                            "mean_rgb_abs": ImageStat.Stat(ImageChops.difference(a.crop(box), b.crop(box))).mean}
                           for box in boxes]
                passed = (max(ImageStat.Stat(a).stddev) > 2 and max(error) <= min(6.0, tolerance)
                          and all(max(row["mean_rgb_abs"]) <= min(6.0, tolerance) for row in regions))
            result["poses"].append({"pose": pose, "passed": passed, "mean_rgb_abs": error,
                                    "regions": regions, "atlas_mips": mip_evidence})
    except (OSError, KeyError, TypeError, ValueError) as error:
        return {**result, "reason": str(error)}
    return {**result, "passed": len(result["poses"]) == 7 and all(row["passed"] for row in result["poses"])}


def color_ratio_vector(stats: dict[str, object]) -> tuple[float, float, float]:
    dominant = [
        float(stats.get("dominant_red_pixels") or 0),
        float(stats.get("dominant_green_pixels") or 0),
        float(stats.get("dominant_blue_pixels") or 0),
    ]
    if sum(dominant) > 0:
        total = sum(dominant)
        return tuple(value / total for value in dominant)
    total = max(1.0, float(stats.get("red_sum") or 0) + float(stats.get("green_sum") or 0) + float(stats.get("blue_sum") or 0))
    return (
        float(stats.get("red_sum") or 0) / total,
        float(stats.get("green_sum") or 0) / total,
        float(stats.get("blue_sum") or 0) / total,
    )


def translucent_overlap_crop_stats(rgb: Any) -> dict[str, object]:
    width, height = rgb.size
    candidates: list[tuple[int, int, int, int, int, int]] = []
    red_sum = 0
    green_sum = 0
    blue_sum = 0
    dominant_red_pixels = 0
    dominant_green_pixels = 0
    dominant_blue_pixels = 0
    edge_like = 0
    for y in range(0, int(height * 0.82)):
        for x in range(0, width):
            red, green, blue = rgb.getpixel((x, y))
            if blue > 145 and green > 95 and red < 170:
                continue
            chroma = max(red, green, blue) - min(red, green, blue)
            filled = (
                chroma >= 14
                and (
                    red > green + 7
                    or green > red + 7
                    or blue > red + 7
                )
                and not (green > red + 18 and green > blue + 18 and y > height * 0.45)
            )
            if not filled:
                continue
            candidates.append((x, y, red, green, blue, chroma))
            red_sum += red
            green_sum += green
            blue_sum += blue
            dominant = max(range(3), key=lambda channel: (red, green, blue)[channel])
            if dominant == 0:
                dominant_red_pixels += 1
            elif dominant == 1:
                dominant_green_pixels += 1
            else:
                dominant_blue_pixels += 1
            if chroma > 80:
                edge_like += 1
    if len(candidates) < 900:
        return {"status": "missing_filled_overlap", "filled_pixels": len(candidates)}
    xs = [item[0] for item in candidates]
    ys = [item[1] for item in candidates]
    left = max(0, min(xs) - 4)
    top = max(0, min(ys) - 4)
    right = min(width, max(xs) + 5)
    bottom = min(height, max(ys) + 5)
    if right - left < 24 or bottom - top < 24:
        return {"status": "edge_only_overlap", "filled_pixels": len(candidates)}
    return {
        "status": "present",
        "filled_pixels": len(candidates),
        "red_sum": red_sum,
        "green_sum": green_sum,
        "blue_sum": blue_sum,
        "dominant_red_pixels": dominant_red_pixels,
        "dominant_green_pixels": dominant_green_pixels,
        "dominant_blue_pixels": dominant_blue_pixels,
        "edge_ratio": edge_like / max(1, len(candidates)),
        "crop": (left, top, right, bottom),
    }


def static_terrain_translucent_camera_sequence_evidence(doc: dict[str, object] | None) -> dict[str, object]:
    if not isinstance(doc, dict):
        return {"status": "skip", "failure": None, "capture_count": 0}
    captures = doc.get("captures")
    if not isinstance(captures, list):
        captures = []
    pose_sequence = doc.get("poseSequence")
    if not isinstance(pose_sequence, list):
        pose_sequence = []
    expected = [
        "translucent-front",
        "translucent-lateral",
        "translucent-orbit-left",
        "translucent-cross-opposite",
        "translucent-above",
        "translucent-below",
        "translucent-return",
    ]
    failures: list[str] = []
    names = [str(item.get("poseName") or "") for item in captures if isinstance(item, dict)]
    if len(captures) < len(expected):
        failures.append("terrain_translucent_camera_sequence_missing")
    if names[: len(expected)] != expected:
        failures.append("terrain_translucent_camera_sequence_wrong_order")
    positions: list[tuple[float, float, float]] = []
    for item in captures:
        if not isinstance(item, dict):
            continue
        position = item.get("position")
        if not isinstance(position, dict):
            continue
        x = parse_number(position.get("x"))
        y = parse_number(position.get("y"))
        z = parse_number(position.get("z"))
        if x is None or y is None or z is None:
            continue
        positions.append((float(x), float(y), float(z)))
    unique_positions = {
        (round(x, 3), round(y, 3), round(z, 3))
        for x, y, z in positions
    }
    horizontal_span = 0.0
    vertical_span = 0.0
    if positions:
        xs = [x for x, _, _ in positions]
        ys = [y for _, y, _ in positions]
        zs = [z for _, _, z in positions]
        horizontal_span = math.hypot(max(xs) - min(xs), max(zs) - min(zs))
        vertical_span = max(ys) - min(ys)
    if len(unique_positions) < 5 or horizontal_span < 8.0 or vertical_span < 8.0:
        failures.append("terrain_translucent_camera_sequence_no_crossing")
    unique_failures = sorted(set(failures))
    return {
        "status": "pass" if not unique_failures else "fail",
        "failure": unique_failures[0] if unique_failures else None,
        "failures": unique_failures,
        "capture_count": len(captures),
        "pose_sequence": [str(item) for item in pose_sequence],
        "captured_pose_names": names,
        "unique_positions": len(unique_positions),
        "horizontal_span": horizontal_span,
        "vertical_span": vertical_span,
    }


